// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import '../gauge/interfaces/ILeafVoter.sol';
import './CLPool.sol';
import './indexation/CLFactoryIndexation.sol';
import './interfaces/ICLFactory.sol';
import './interfaces/IFactoryRegistry.sol';
import './interfaces/fees/IFeeModule.sol';
import '@openzeppelin/contracts/proxy/Clones.sol';

/// @title Canonical CL factory
/// @notice Deploys CL pools and manages ownership and control over pool protocol fees
contract CLFactory is CLFactoryIndexation, ICLFactory {
  /// @inheritdoc ICLFactory
  ILeafVoter public override voter;
  /// @inheritdoc ICLFactory
  address public immutable override poolImplementation;
  /// @inheritdoc ICLFactory
  address public immutable override positionManager;
  /// @inheritdoc ICLFactory
  IFactoryRegistry public immutable override factoryRegistry;
  /// @inheritdoc ICLFactory
  address public override owner;
  /// @inheritdoc ICLFactory
  address public override swapFeeManager;
  /// @inheritdoc ICLFactory
  address public override unstakedFeeManager;
  /// @inheritdoc ICLFactory
  address public override unstakedFeeModule;
  /// @inheritdoc ICLFactory
  address public override defaultSwapHook;
  /// @inheritdoc ICLFactory
  mapping(address => address) public override poolSwapHook;
  /// @inheritdoc ICLFactory
  uint24 public override defaultUnstakedFee;
  /// @inheritdoc ICLFactory
  address public override discountRegistryManager;
  /// @inheritdoc ICLFactory
  address public override discountRegistry;
  /// @inheritdoc ICLFactory
  address public override clPoolTape;
  /// @inheritdoc ICLFactory
  address public override clPoolTapeManager;

  /// @inheritdoc ICLFactory
  mapping(int24 => uint24) public override tickSpacingToFee;
  /// @dev Used in VotingEscrow to determine if a contract is a valid pool
  mapping(address => bool) private _isPool;
  /// @inheritdoc ICLFactory
  address[] public override allPools;

  int24[] private _tickSpacings;
  mapping(address => mapping(address => mapping(int24 => address))) internal _getPool;

  constructor(ConstructorParams memory _params) {
    require(_params.owner != address(0), 'OwnerIsZero');
    require(_params.swapFeeManager != address(0), 'SwapFeeManagerIsZero');
    require(_params.unstakedFeeManager != address(0), 'UnstakedFeeManagerIsZero');
    require(_params.poolImplementation != address(0), 'PoolImplementationIsZero');
    require(_params.positionManager != address(0), 'PositionManagerIsZero');
    require(_params.factoryRegistry != address(0), 'FactoryRegistryIsZero');
    require(_params.discountRegistryManager != address(0), 'DiscountRegistryManagerIsZero');
    require(_params.clPoolTapeManager != address(0), 'ClPoolTapeManagerIsZero');
    owner = _params.owner;
    swapFeeManager = _params.swapFeeManager;
    unstakedFeeManager = _params.unstakedFeeManager;
    voter = ILeafVoter(_params.voter);
    poolImplementation = _params.poolImplementation;
    positionManager = _params.positionManager;
    factoryRegistry = IFactoryRegistry(_params.factoryRegistry);
    defaultSwapHook = _params.defaultSwapHook;
    discountRegistryManager = _params.discountRegistryManager;
    clPoolTapeManager = _params.clPoolTapeManager;
    defaultUnstakedFee = 0;
    emit OwnerChanged(address(0), _params.owner);
    emit SwapFeeManagerChanged(address(0), _params.swapFeeManager);
    emit UnstakedFeeManagerChanged(address(0), _params.unstakedFeeManager);
    emit DefaultUnstakedFeeChanged(0, 0);
    emit DefaultSwapHookChanged(_params.defaultSwapHook);
    emit DiscountRegistryManagerChanged(_params.discountRegistryManager);
    emit ClPoolTapeManagerChanged(_params.clPoolTapeManager);

    for (uint256 i; i < _params.initialFeeTiers.length; ++i) {
      enableTickSpacing(_params.initialFeeTiers[i].tickSpacing, _params.initialFeeTiers[i].fee);
    }
  }

  /// @inheritdoc ICLFactory
  function createPool(address tokenA, address tokenB, uint24 tickSpacing) external override returns (address) {
    return createPool({
      tokenA: tokenA,
      tokenB: tokenB,
      tickSpacing: int24(tickSpacing),
      sqrtPriceX96: 79_228_162_514_264_337_593_543_950_336 // encodePriceSqrt(1, 1)
    });
  }

  /// @inheritdoc ICLFactory
  function createPool(
    address tokenA,
    address tokenB,
    int24 tickSpacing,
    uint160 sqrtPriceX96
  ) public override returns (address pool) {
    require(tokenA != tokenB);
    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0));
    require(tickSpacingToFee[tickSpacing] != 0);
    require(_getPool[token0][token1][tickSpacing] == address(0));
    pool =
      Clones.cloneDeterministic({master: poolImplementation, salt: keccak256(abi.encode(token0, token1, tickSpacing))});
    CLPool(pool).initialize({
      _factory: address(this),
      _token0: token0,
      _token1: token1,
      _tickSpacing: tickSpacing,
      _factoryRegistry: address(factoryRegistry),
      _sqrtPriceX96: sqrtPriceX96
    });
    allPools.push(pool);
    _isPool[pool] = true;
    _getPool[token0][token1][tickSpacing] = pool;
    // populate mapping in the reverse direction, deliberate choice to avoid the cost of comparing addresses
    _getPool[token1][token0][tickSpacing] = pool;

    /// @dev This function is invoked only after the pool is deployed
    ///      and only after all validations are passed.
    _createPoolHook({_tokenA: tokenA, _tokenB: tokenB, _pool: pool});

    /// @dev Records the pool as a target so gauges can be created for it. Reverts until
    ///      this factory is approved as a target factory in the registry.
    factoryRegistry.registerTarget(pool);

    emit PoolCreated(token0, token1, tickSpacing, pool);
  }

  /// @inheritdoc ICLFactory
  function setOwner(address _owner) external override {
    address cachedOwner = owner;
    require(msg.sender == cachedOwner);
    require(_owner != address(0));
    emit OwnerChanged(cachedOwner, _owner);
    owner = _owner;
  }

  /// @inheritdoc ICLFactory
  function setVoter(address _voter) external override {
    require(msg.sender == owner, 'NotOwner');
    require(address(voter) == address(0), 'VoterAlreadySet');
    require(_voter != address(0), 'VoterIsZero');
    voter = ILeafVoter(_voter);
    emit VoterSet(_voter);
  }

  /// @inheritdoc ICLFactory
  function setSwapFeeManager(address _swapFeeManager) external override {
    address cachedSwapFeeManager = swapFeeManager;
    require(msg.sender == cachedSwapFeeManager);
    require(_swapFeeManager != address(0));
    swapFeeManager = _swapFeeManager;
    emit SwapFeeManagerChanged(cachedSwapFeeManager, _swapFeeManager);
  }

  /// @inheritdoc ICLFactory
  function setUnstakedFeeManager(address _unstakedFeeManager) external override {
    address cachedUnstakedFeeManager = unstakedFeeManager;
    require(msg.sender == cachedUnstakedFeeManager);
    require(_unstakedFeeManager != address(0));
    unstakedFeeManager = _unstakedFeeManager;
    emit UnstakedFeeManagerChanged(cachedUnstakedFeeManager, _unstakedFeeManager);
  }

  /// @inheritdoc ICLFactory
  function setDiscountRegistryManager(address _discountRegistryManager) external override {
    require(msg.sender == discountRegistryManager, 'NotDiscountRegistryManager');
    require(_discountRegistryManager != address(0), 'DiscountRegistryManagerIsZero');

    discountRegistryManager = _discountRegistryManager;
    emit DiscountRegistryManagerChanged(_discountRegistryManager);
  }

  /// @inheritdoc ICLFactory
  function setUnstakedFeeModule(address _unstakedFeeModule) external override {
    require(msg.sender == unstakedFeeManager);
    require(_unstakedFeeModule != address(0));
    address oldFeeModule = unstakedFeeModule;
    unstakedFeeModule = _unstakedFeeModule;
    emit UnstakedFeeModuleChanged(oldFeeModule, _unstakedFeeModule);
  }

  /// @inheritdoc ICLFactory
  function setDefaultUnstakedFee(uint24 _defaultUnstakedFee) external override {
    require(msg.sender == unstakedFeeManager);
    require(_defaultUnstakedFee <= 500_000);
    uint24 oldUnstakedFee = defaultUnstakedFee;
    defaultUnstakedFee = _defaultUnstakedFee;
    emit DefaultUnstakedFeeChanged(oldUnstakedFee, _defaultUnstakedFee);
  }

  /// @inheritdoc ICLFactory
  function setDefaultSwapHook(address _swapHook) external override {
    require(msg.sender == swapFeeManager, 'NotSwapFeeManager');
    defaultSwapHook = _swapHook;

    emit DefaultSwapHookChanged(_swapHook);
  }

  /// @inheritdoc ICLFactory
  function getPoolSwapHook(address _pool) external view override returns (address) {
    address poolHook = poolSwapHook[_pool];
    return poolHook == address(0) ? defaultSwapHook : poolHook;
  }

  /// @inheritdoc ICLFactory
  function setPoolSwapHook(address[] calldata _pools, address[] calldata _swapHooks) external override {
    require(msg.sender == swapFeeManager, 'NotSwapFeeManager');
    uint256 poolsLength = _pools.length;
    require(poolsLength == _swapHooks.length, 'LMM');

    address pool;
    address hook;
    for (uint256 i = 0; i < poolsLength; i++) {
      pool = _pools[i];
      hook = _swapHooks[i];
      poolSwapHook[pool] = hook;
      emit PoolSwapHookChanged(pool, hook);
    }
  }

  /// @inheritdoc ICLFactory
  function setDiscountRegistry(address _discountRegistry) external override {
    require(msg.sender == discountRegistryManager, 'NotDiscountRegistryManager');
    require(_discountRegistry != address(0), 'DiscountRegistryIsZero');

    discountRegistry = _discountRegistry;

    emit DiscountRegistryChanged(_discountRegistry);
  }

  /// @inheritdoc ICLFactory
  function setClPoolTapeManager(address _clPoolTapeManager) external override {
    require(msg.sender == clPoolTapeManager, 'NotClPoolTapeManager');
    require(_clPoolTapeManager != address(0), 'ClPoolTapeManagerIsZero');
    clPoolTapeManager = _clPoolTapeManager;
    emit ClPoolTapeManagerChanged(_clPoolTapeManager);
  }

  /// @inheritdoc ICLFactory
  function setClPoolTape(address _clPoolTape) external override {
    require(msg.sender == clPoolTapeManager, 'NotClPoolTapeManager');
    clPoolTape = _clPoolTape;
    emit ClPoolTapeChanged(_clPoolTape);
  }

  /// @inheritdoc ICLFactory
  function getUnstakedFee(address pool) external view override returns (uint24) {
    ILeafVoter _leafVoter = voter;
    if (address(_leafVoter) == address(0)) {
      return 0;
    }
    address gauge = factoryRegistry.targetToGauge(pool);
    // a zero emission cap disables fee collection on the gauge, so stop charging the fee
    if (gauge == address(0) || !_leafVoter.isActivated(gauge) || factoryRegistry.emissionCap(gauge) == 0) {
      return 0;
    }

    if (unstakedFeeModule != address(0)) {
      try IFeeModule(unstakedFeeModule).getFee(pool) returns (uint24 fee) {
        if (fee <= 1_000_000) return fee;
      } catch {}
    }
    return defaultUnstakedFee;
  }

  /// @inheritdoc ICLFactory
  function enableTickSpacing(int24 tickSpacing, uint24 fee) public override {
    require(msg.sender == owner);
    require(fee > 0 && fee <= 100_000);
    // tick spacing is capped at 16384 to prevent the situation where tickSpacing is so large that
    // TickBitmap#nextInitializedTickWithinOneWord overflows int24 container from a valid tick
    // 16384 ticks represents a >5x price change with ticks of 1 bips
    require(tickSpacing > 0 && tickSpacing < 16_384);
    require(tickSpacingToFee[tickSpacing] == 0);

    tickSpacingToFee[tickSpacing] = fee;
    _tickSpacings.push(tickSpacing);
    emit TickSpacingEnabled(tickSpacing, fee);
  }

  function getPool(address tokenA, address tokenB, int24 tickSpacing) external view override returns (address) {
    return _getPool[tokenA][tokenB][tickSpacing];
  }

  function getPool(address tokenA, address tokenB, uint24 tickSpacing) external view override returns (address) {
    return _getPool[tokenA][tokenB][int24(tickSpacing)];
  }

  /// @inheritdoc ICLFactory
  function tickSpacings() external view override returns (int24[] memory) {
    return _tickSpacings;
  }

  /// @inheritdoc ICLFactory
  function allPoolsLength() external view override returns (uint256) {
    return allPools.length;
  }

  /// @inheritdoc ICLFactory
  function isPool(address pool) external view override returns (bool) {
    return _isPool[pool];
  }
}

contracts/core/CLPool.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import './interfaces/ICLPool.sol';

import './libraries/LowGasSafeMath.sol';
import './libraries/Oracle.sol';
import './libraries/Position.sol';
import './libraries/SafeCast.sol';
import './libraries/Tick.sol';
import './libraries/TickBitmap.sol';

import {CLPoolNonSwapPath as CL} from './libraries/CLPoolNonSwapPath.sol';
import './libraries/FixedPoint128.sol';
import './libraries/FullMath.sol';
import './libraries/LiquidityMath.sol';
import './libraries/SwapMath.sol';
import './libraries/TickMath.sol';
import './libraries/TransferHelper.sol';
import './libraries/hook/SwapHookLib.sol';

import './interfaces/ICLFactory.sol';
import './interfaces/IERC20Minimal.sol';
import './interfaces/IFactoryRegistry.sol';
import './interfaces/callback/ICLSwapCallback.sol';
import './interfaces/hook/ISwapHook.sol';
import {ICLGauge} from 'contracts/gauge/interfaces/ICLGauge.sol';

contract CLPool is ICLPool {
  using LowGasSafeMath for uint256;
  using LowGasSafeMath for int256;
  using SafeCast for uint256;
  using SafeCast for int256;
  using Tick for mapping(int24 => Tick.Info);
  using TickBitmap for mapping(int16 => uint256);
  using Position for mapping(bytes32 => Position.Info);
  using Position for Position.Info;
  using Oracle for Oracle.Observation[65_535];
  using SwapHookLib for address;

  /// @inheritdoc ICLPoolConstants
  address public override factory;
  /// @inheritdoc ICLPoolConstants
  address public override token0;
  /// @inheritdoc ICLPoolConstants
  address public override token1;
  /// @inheritdoc ICLPoolConstants
  address public override gauge;
  /// @inheritdoc ICLPoolConstants
  address public override nft;
  /// @inheritdoc ICLPoolConstants
  address public override factoryRegistry;

  struct Slot0 {
    // the current price
    uint160 sqrtPriceX96;
    // the current tick
    int24 tick;
    // the most-recently updated index of the observations array
    uint16 observationIndex;
    // the current maximum number of observations that are being stored
    uint16 observationCardinality;
    // the next maximum number of observations to store, triggered in observations.write
    uint16 observationCardinalityNext;
    // whether the pool is locked
    bool unlocked;
  }

  /// @inheritdoc ICLPoolState
  Slot0 public override slot0;

  /// @inheritdoc ICLPoolState
  uint256 public override feeGrowthGlobal0X128;
  /// @inheritdoc ICLPoolState
  uint256 public override feeGrowthGlobal1X128;

  /// @inheritdoc ICLPoolState
  uint256 public override rewardGrowthGlobalX128;

  // accumulated gauge fees in token0/token1 units
  struct GaugeFees {
    uint128 token0;
    uint128 token1;
  }

  /// @inheritdoc ICLPoolState
  GaugeFees public override gaugeFees;

  /// @inheritdoc ICLPoolState
  uint256 public override rollover;

  /// @inheritdoc ICLPoolState
  uint128 public override stakedLiquidity;
  /// @inheritdoc ICLPoolState
  uint48 public override lastUpdated;
  /// @inheritdoc ICLPoolConstants
  int24 public override tickSpacing;

  /// @inheritdoc ICLPoolState
  uint128 public override liquidity;
  /// @inheritdoc ICLPoolConstants
  uint128 public override maxLiquidityPerTick;

  /// @inheritdoc ICLPoolState
  mapping(int24 => Tick.Info) public override ticks;
  /// @inheritdoc ICLPoolState
  mapping(int16 => uint256) public override tickBitmap;
  /// @inheritdoc ICLPoolState
  mapping(bytes32 => Position.Info) public override positions;
  /// @inheritdoc ICLPoolState
  Oracle.Observation[65_535] public override observations;

  /// @inheritdoc ICLPoolState
  uint160 public override secondsPerStakedLiquidityCumulativeX128;

  /// @inheritdoc ICLPoolConstants
  uint256 public constant override SWAP_FEE_CEIL = 100_000;
  /// @inheritdoc ICLPoolConstants
  uint256 public constant override DENOMINATOR = 1_000_000;
  /// @inheritdoc ICLPoolConstants
  bytes32 public constant override POOL_TYPE = 'CL';

  /// @dev Mutually exclusive reentrancy protection into the pool to/from a method. This method also prevents entrance
  /// to a function before the pool is initialized. The reentrancy guard is required throughout the contract because
  /// we use balance checks to determine the payment status of interactions such as mint, swap and flash.
  function _lock() private {
    _require(slot0.unlocked, 'LOK');
    slot0.unlocked = false;
  }

  function _unlock() private {
    slot0.unlocked = true;
  }

  function _require(bool condition, string memory error) private pure {
    require(condition, error);
  }

  /// @dev Prevents calling a function from anyone except the gauge associated with this pool
  function _onlyGauge() private view {
    _require(msg.sender == gauge, 'NG');
  }

  /// @dev Prevents calling a function from anyone except the nft manager
  function _onlyNftManager() private view {
    _require(msg.sender == nft, 'NNFT');
  }

  /// @inheritdoc ICLPoolActions
  function initialize(
    address _factory,
    address _token0,
    address _token1,
    int24 _tickSpacing,
    address _factoryRegistry,
    uint160 _sqrtPriceX96
  ) external override {
    require(factory == address(0) && _factory != address(0));
    factory = _factory;
    token0 = _token0;
    token1 = _token1;
    tickSpacing = _tickSpacing;
    factoryRegistry = _factoryRegistry;

    maxLiquidityPerTick =
      CL.initializeSlot0(slot0, observations, _sqrtPriceX96, TickMath.getTickAtSqrtRatio(_sqrtPriceX96), _tickSpacing);
  }

  /// @inheritdoc ICLPoolState
  function beforeSwapFee(ISwapHook.SwapParams memory _swapParams) public view override returns (uint24) {
    return CL.beforeSwapFee(_swapParams, factory, tickSpacing);
  }

  /// @inheritdoc ICLPoolState
  function afterSwapFee(
    ISwapHook.SwapParams memory _swapParams,
    ISwapHook.AfterSwapParams memory _afterSwapParams
  ) external view override returns (uint24) {
    return CL.afterSwapFee(_swapParams, _afterSwapParams, factory);
  }

  /// @inheritdoc ICLPoolState
  function flashFee(ISwapHook.FlashParams memory _flashParams) external view override returns (uint24 _fee) {
    return CL.flashFee(_flashParams, factory, tickSpacing);
  }

  /// @inheritdoc ICLPoolState
  /// @dev This method can be used for "legacy" swap fee modules.
  function fee() external view override returns (uint24) {
    ISwapHook.SwapParams memory _swapParams;
    _swapParams.caller = msg.sender;
    return beforeSwapFee(_swapParams);
  }

  /// @inheritdoc ICLPoolState
  function unstakedFee() public view override returns (uint24) {
    return ICLFactory(factory).getUnstakedFee(address(this));
  }

  /// @dev Common checks for valid tick inputs.
  function checkTicks(int24 tickLower, int24 tickUpper) private pure {
    require(tickLower < tickUpper, 'TLU');
    require(tickLower >= TickMath.MIN_TICK, 'TLM');
    require(tickUpper <= TickMath.MAX_TICK, 'TUM');
  }

  /// @dev Get the pool's balance of token0
  /// @dev This function is gas optimized to avoid a redundant extcodesize check in addition to the returndatasize
  /// check
  function balance0() private view returns (uint256) {
    return IERC20Minimal(token0).balanceOf(address(this));
  }

  /// @dev Get the pool's balance of token1
  /// @dev This function is gas optimized to avoid a redundant extcodesize check in addition to the returndatasize
  /// check
  function balance1() private view returns (uint256) {
    return IERC20Minimal(token1).balanceOf(address(this));
  }

  /// @inheritdoc ICLPoolDerivedState
  function snapshotCumulativesInside(
    int24 tickLower,
    int24 tickUpper
  )
    external
    view
    override
    returns (int56 tickCumulativeInside, uint160 secondsPerLiquidityInsideX128, uint32 secondsInside)
  {
    Slot0 memory currentSlot0 = slot0;
    return CL.snapshotCumulativesInside(
      ticks,
      observations,
      tickLower,
      tickUpper,
      currentSlot0.tick,
      currentSlot0.observationIndex,
      currentSlot0.observationCardinality,
      liquidity
    );
  }

  /// @inheritdoc ICLPoolDerivedState
  function observe(uint32[] calldata secondsAgos)
    external
    view
    override
    returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s)
  {
    return observations.observe(
      uint32(block.timestamp), secondsAgos, slot0.tick, slot0.observationIndex, liquidity, slot0.observationCardinality
    );
  }

  /// @inheritdoc ICLPoolDerivedState
  function getSecondsPerStakedLiquidityCumulativeX128() external view override returns (uint160 _cumulative) {
    _cumulative = secondsPerStakedLiquidityCumulativeX128;
    uint128 _stakedLiquidity = stakedLiquidity;
    if (_stakedLiquidity > 0) {
      _cumulative += _secondsPerStakedLiquidityDelta(block.timestamp - lastUpdated, _stakedLiquidity);
    }
  }

  /// @inheritdoc ICLPoolActions
  function increaseObservationCardinalityNext(uint16 observationCardinalityNext) external override {
    _lock();
    CL.increaseObservationCardinalityNext(observations, slot0, observationCardinalityNext);
    _unlock();
  }

  /// @inheritdoc ICLPoolState
  function getFeeGrowthInside(
    int24 tickLower,
    int24 tickUpper
  ) external view override returns (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128) {
    return CL.getFeeGrowthInside(ticks, tickLower, tickUpper, slot0.tick, feeGrowthGlobal0X128, feeGrowthGlobal1X128);
  }

  function _modifyPositionInput(
    address owner,
    int24 tickLower,
    int24 tickUpper
  ) private view returns (CL.ModifyPositionInput memory input) {
    input = CL.ModifyPositionInput({
      owner: owner,
      tickLower: tickLower,
      tickUpper: tickUpper,
      liquidity: liquidity,
      maxLiquidityPerTick: maxLiquidityPerTick,
      feeGrowthGlobal0X128: feeGrowthGlobal0X128,
      feeGrowthGlobal1X128: feeGrowthGlobal1X128,
      rewardGrowthGlobalX128: rewardGrowthGlobalX128,
      gauge: gauge,
      tickSpacing: tickSpacing,
      amount: 0
    });
  }

  /// @inheritdoc ICLPoolActions
  function mint(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    bytes calldata data
  ) external override returns (uint256 amount0, uint256 amount1) {
    _lock();
    CL.ModifyPositionInput memory input = _modifyPositionInput(recipient, tickLower, tickUpper);
    input.amount = amount;
    (uint128 liquidityAfter, uint256 amount0Out, uint256 amount1Out) =
      CL.modifyPositionForMint(positions, ticks, tickBitmap, observations, slot0, input);
    liquidity = liquidityAfter;
    CL.settleMint(input, amount0Out, amount1Out, token0, token1, data);
    _unlock();
    return (amount0Out, amount1Out);
  }

  /// @inheritdoc ICLPoolActions
  function collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested
  ) external override returns (uint128 amount0, uint128 amount1) {
    _lock();
    (amount0, amount1) = _collect({
      recipient: recipient,
      tickLower: tickLower,
      tickUpper: tickUpper,
      amount0Requested: amount0Requested,
      amount1Requested: amount1Requested,
      owner: msg.sender
    });
    _unlock();
  }

  /// @inheritdoc ICLPoolActions
  function collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested,
    address owner
  ) external override returns (uint128 amount0, uint128 amount1) {
    _lock();
    _onlyNftManager();
    (amount0, amount1) = _collect({
      recipient: recipient,
      tickLower: tickLower,
      tickUpper: tickUpper,
      amount0Requested: amount0Requested,
      amount1Requested: amount1Requested,
      owner: owner
    });
    _unlock();
  }

  function _collect(
    address recipient,
    int24 tickLower,
    int24 tickUpper,
    uint128 amount0Requested,
    uint128 amount1Requested,
    address owner
  ) private returns (uint128 amount0, uint128 amount1) {
    return CL.collect(
      positions, recipient, tickLower, tickUpper, amount0Requested, amount1Requested, owner, token0, token1
    );
  }

  /// @inheritdoc ICLPoolActions
  function burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount
  ) external override returns (uint256 amount0, uint256 amount1) {
    _lock();
    (amount0, amount1) = _burn({tickLower: tickLower, tickUpper: tickUpper, amount: amount, owner: msg.sender});
    _unlock();
  }

  /// @inheritdoc ICLPoolActions
  function burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    address owner
  ) external override returns (uint256 amount0, uint256 amount1) {
    _lock();
    _onlyNftManager();
    (amount0, amount1) = _burn({tickLower: tickLower, tickUpper: tickUpper, amount: amount, owner: owner});
    _unlock();
  }

  function _burn(
    int24 tickLower,
    int24 tickUpper,
    uint128 amount,
    address owner
  ) private returns (uint256 amount0, uint256 amount1) {
    CL.ModifyPositionInput memory input = _modifyPositionInput(owner, tickLower, tickUpper);
    input.amount = amount;
    (uint128 liquidityAfter, uint256 amount0Out, uint256 amount1Out) =
      CL.burn(positions, ticks, tickBitmap, observations, slot0, input);
    liquidity = liquidityAfter;
    return (amount0Out, amount1Out);
  }

  /// @inheritdoc ICLPoolActions
  function stake(int128 stakedLiquidityDelta, int24 tickLower, int24 tickUpper) external override {
    _lock();
    _onlyGauge();
    int24 tick = slot0.tick;
    // Increase staked liquidity in the current tick
    if (tick >= tickLower && tick < tickUpper) {
      _settleToBlock();
      stakedLiquidity = LiquidityMath.addDelta(stakedLiquidity, stakedLiquidityDelta);
    }

    CL.stakePositions(
      positions,
      ticks,
      nft,
      tickLower,
      tickUpper,
      tick,
      stakedLiquidityDelta,
      feeGrowthGlobal0X128,
      feeGrowthGlobal1X128
    );
    _unlock();
  }

  struct SwapCache {
    // liquidity at the beginning of the swap
    uint128 liquidityStart;
    // staked liquidity at the beginning of the swap
    uint128 stakedLiquidityStart;
    // the timestamp of the current block
    uint32 blockTimestamp;
    // the current value of the tick accumulator, computed only if we cross an initialized tick
    int56 tickCumulative;
    // the current value of seconds per liquidity accumulator, computed only if we cross an initialized tick
    uint160 secondsPerLiquidityCumulativeX128;
    // whether we've computed and cached the above two accumulators
    bool computedLatestObservation;
    // global swap hook used to call beforeSwap/afterSwap methods.
    address swapHook;
  }

  // the top level state of the swap, the results of which are recorded in storage at the end
  struct SwapState {
    // the amount remaining to be swapped in/out of the input/output asset
    int256 amountSpecifiedRemaining;
    // the amount already swapped out/in of the output/input asset
    int256 amountCalculated;
    // current sqrt(price)
    uint160 sqrtPriceX96;
    // the tick associated with the current price
    int24 tick;
    // the fee associated with the pool
    uint24 fee;
    // wether we've updated the fees in the current swap
    bool hasUpdatedFees;
    // the global fee growth of the input token
    uint256 feeGrowthGlobalX128;
    // amount of input token paid as gauge fee
    uint128 gaugeFee;
    // the current liquidity in range
    uint128 liquidity;
    // the current staked liquidity in range
    uint128 stakedLiquidity;
  }

  struct StepComputations {
    // the price at the beginning of the step
    uint160 sqrtPriceStartX96;
    // the next tick to swap to from the current tick in the swap direction
    int24 tickNext;
    // whether tickNext is initialized or not
    bool initialized;
    // sqrt(price) for the next tick (1/0)
    uint160 sqrtPriceNextX96;
    // how much is being swapped in in this step
    uint256 amountIn;
    // how much is being swapped out
    uint256 amountOut;
    // how much fee is being paid in
    uint256 feeAmount;
  }

  /// @inheritdoc ICLPoolActions
  function swap(
    address recipient,
    bool zeroForOne,
    int256 amountSpecified,
    uint160 sqrtPriceLimitX96,
    bytes calldata data
  ) external override returns (int256 amount0, int256 amount1) {
    _require(amountSpecified != 0, 'AS');

    Slot0 memory slot0Start = slot0;

    _require(slot0Start.unlocked, 'LOK');
    _require(
      zeroForOne
        ? sqrtPriceLimitX96 < slot0Start.sqrtPriceX96 && sqrtPriceLimitX96 > TickMath.MIN_SQRT_RATIO
        : sqrtPriceLimitX96 > slot0Start.sqrtPriceX96 && sqrtPriceLimitX96 < TickMath.MAX_SQRT_RATIO,
      'SPL'
    );

    slot0.unlocked = false;

    SwapCache memory cache = SwapCache({
      liquidityStart: liquidity,
      stakedLiquidityStart: stakedLiquidity,
      blockTimestamp: uint32(block.timestamp),
      secondsPerLiquidityCumulativeX128: 0,
      tickCumulative: 0,
      computedLatestObservation: false,
      swapHook: ICLFactory(factory).getPoolSwapHook(address(this))
    });

    bool exactInput = amountSpecified > 0;

    SwapState memory state = SwapState({
      amountSpecifiedRemaining: amountSpecified,
      amountCalculated: 0,
      sqrtPriceX96: slot0Start.sqrtPriceX96,
      tick: slot0Start.tick,
      fee: 0, // set below
      hasUpdatedFees: false,
      feeGrowthGlobalX128: zeroForOne ? feeGrowthGlobal0X128 : feeGrowthGlobal1X128,
      gaugeFee: 0,
      liquidity: cache.liquidityStart,
      stakedLiquidity: cache.stakedLiquidityStart
    });

    state.fee = cache.swapHook
      .beforeSwap(
        ISwapHook.SwapParams({
          caller: msg.sender,
          recipient: recipient,
          zeroForOne: zeroForOne,
          amountSpecified: amountSpecified,
          sqrtPriceLimitX96: sqrtPriceLimitX96,
          data: data,
          sqrtPriceX96: slot0Start.sqrtPriceX96,
          tick: slot0Start.tick
        }),
        factory,
        tickSpacing
      );

    // continue swapping as long as we haven't used the entire input/output and haven't reached the price limit
    while (state.amountSpecifiedRemaining != 0 && state.sqrtPriceX96 != sqrtPriceLimitX96) {
      StepComputations memory step;

      step.sqrtPriceStartX96 = state.sqrtPriceX96;

      (step.tickNext, step.initialized) =
        tickBitmap.nextInitializedTickWithinOneWord(state.tick, tickSpacing, zeroForOne);

      // ensure that we do not overshoot the min/max tick, as the tick bitmap is not aware of these bounds
      if (step.tickNext < TickMath.MIN_TICK) {
        step.tickNext = TickMath.MIN_TICK;
      } else if (step.tickNext > TickMath.MAX_TICK) {
        step.tickNext = TickMath.MAX_TICK;
      }

      // get the price for the next tick
      step.sqrtPriceNextX96 = TickMath.getSqrtRatioAtTick(step.tickNext);

      // compute values to swap to the target tick, price limit, or point where input/output amount is exhausted
      (state.sqrtPriceX96, step.amountIn, step.amountOut, step.feeAmount) = SwapMath.computeSwapStep(
        state.sqrtPriceX96,
        (zeroForOne ? step.sqrtPriceNextX96 < sqrtPriceLimitX96 : step.sqrtPriceNextX96 > sqrtPriceLimitX96)
          ? sqrtPriceLimitX96
          : step.sqrtPriceNextX96,
        state.liquidity,
        state.amountSpecifiedRemaining,
        state.fee
      );

      if (exactInput) {
        state.amountSpecifiedRemaining -= (step.amountIn + step.feeAmount).toInt256();
        state.amountCalculated = state.amountCalculated.sub(step.amountOut.toInt256());
      } else {
        state.amountSpecifiedRemaining += step.amountOut.toInt256();
        state.amountCalculated = state.amountCalculated.add((step.amountIn + step.feeAmount).toInt256());
      }

      // update global fee tracker and gauge fee
      if (state.liquidity > 0) {
        (uint256 _feeGrowthGlobalX128, uint256 _stakedFeeAmount) =
          calculateFees(step.feeAmount, state.liquidity, state.stakedLiquidity);

        state.feeGrowthGlobalX128 += _feeGrowthGlobalX128;
        state.gaugeFee += uint128(_stakedFeeAmount);
      }

      // shift tick if we reached the next price
      if (state.sqrtPriceX96 == step.sqrtPriceNextX96) {
        // if the tick is initialized, run the tick transition
        if (step.initialized) {
          // check for the placeholder value, which we replace with the actual value the first time the swap
          // crosses an initialized tick
          if (!cache.computedLatestObservation) {
            (cache.tickCumulative, cache.secondsPerLiquidityCumulativeX128) = observations.observeSingle(
              cache.blockTimestamp,
              0,
              slot0Start.tick,
              slot0Start.observationIndex,
              cache.liquidityStart,
              slot0Start.observationCardinality
            );
            cache.computedLatestObservation = true;
          }
          if (!state.hasUpdatedFees) {
            _settleToBlock();
            state.hasUpdatedFees = true;
          }
          Tick.LiquidityNets memory nets = ticks.cross(
            step.tickNext,
            (zeroForOne ? state.feeGrowthGlobalX128 : feeGrowthGlobal0X128),
            (zeroForOne ? feeGrowthGlobal1X128 : state.feeGrowthGlobalX128),
            cache.secondsPerLiquidityCumulativeX128,
            cache.tickCumulative,
            cache.blockTimestamp,
            rewardGrowthGlobalX128
          );
          // if we're moving leftward, we interpret liquidityNet & stakedLiquidityNet as the opposite sign
          // safe because liquidityNet & stakedLiquidityNet cannot be type(int128).min
          if (zeroForOne) {
            nets.liquidityNet = -nets.liquidityNet;
            nets.stakedLiquidityNet = -nets.stakedLiquidityNet;
          }

          state.liquidity = LiquidityMath.addDelta(state.liquidity, nets.liquidityNet);
          state.stakedLiquidity = LiquidityMath.addDelta(state.stakedLiquidity, nets.stakedLiquidityNet);
        }

        state.tick = zeroForOne ? step.tickNext - 1 : step.tickNext;
      } else if (state.sqrtPriceX96 != step.sqrtPriceStartX96) {
        // recompute unless we're on a lower tick boundary (i.e. already transitioned ticks), and haven't moved
        state.tick = TickMath.getTickAtSqrtRatio(state.sqrtPriceX96);
      }
    }

    /// @dev This function is able to mutate `gaugeFees` storage variable.
    cache.swapHook
      .afterSwap(
        ISwapHook.SwapParams({
          caller: msg.sender,
          recipient: recipient,
          zeroForOne: zeroForOne,
          amountSpecified: amountSpecified,
          sqrtPriceLimitX96: sqrtPriceLimitX96,
          data: data,
          sqrtPriceX96: state.sqrtPriceX96,
          tick: state.tick
        }),
        state,
        cache,
        gaugeFees
      );

    // update tick and write an oracle entry if the tick change
    if (state.tick != slot0Start.tick) {
      (uint16 observationIndex, uint16 observationCardinality) = observations.write(
        slot0Start.observationIndex,
        cache.blockTimestamp,
        slot0Start.tick,
        cache.liquidityStart,
        slot0Start.observationCardinality,
        slot0Start.observationCardinalityNext
      );
      (slot0.sqrtPriceX96, slot0.tick, slot0.observationIndex, slot0.observationCardinality) =
      (state.sqrtPriceX96, state.tick, observationIndex, observationCardinality);
    } else {
      // otherwise just update the price
      slot0.sqrtPriceX96 = state.sqrtPriceX96;
    }

    // update liquidity and stakedLiquidity if it changed
    if (cache.liquidityStart != state.liquidity) liquidity = state.liquidity;
    if (cache.stakedLiquidityStart != state.stakedLiquidity) stakedLiquidity = state.stakedLiquidity;

    // update fee growth global and, if necessary, gauge fees
    // overflow is acceptable, protocol has to withdraw before it hits type(uint128).max fees
    if (zeroForOne) {
      feeGrowthGlobal0X128 = state.feeGrowthGlobalX128;
      if (state.gaugeFee > 0) gaugeFees.token0 += state.gaugeFee;
    } else {
      feeGrowthGlobal1X128 = state.feeGrowthGlobalX128;
      if (state.gaugeFee > 0) gaugeFees.token1 += state.gaugeFee;
    }

    (amount0, amount1) = zeroForOne == exactInput
      ? (amountSpecified - state.amountSpecifiedRemaining, state.amountCalculated)
      : (state.amountCalculated, amountSpecified - state.amountSpecifiedRemaining);

    // do the transfers and collect payment
    if (zeroForOne) {
      if (amount1 < 0) TransferHelper.safeTransfer(token1, recipient, uint256(-amount1));

      uint256 balance0Before = balance0();
      ICLSwapCallback(msg.sender).uniswapV3SwapCallback(amount0, amount1, data);
      _require(balance0Before.add(uint256(amount0)) <= balance0(), 'IIA');
    } else {
      if (amount0 < 0) TransferHelper.safeTransfer(token0, recipient, uint256(-amount0));

      uint256 balance1Before = balance1();
      ICLSwapCallback(msg.sender).uniswapV3SwapCallback(amount0, amount1, data);
      _require(balance1Before.add(uint256(amount1)) <= balance1(), 'IIA');
    }

    emit Swap(msg.sender, recipient, amount0, amount1, state.sqrtPriceX96, state.liquidity, state.tick);
    slot0.unlocked = true;
  }

  /// @inheritdoc ICLPoolActions
  function flash(address recipient, uint256 amount0, uint256 amount1, bytes calldata data) external override {
    _lock();

    /// @dev The internal call credits part of the paid fee to gauge's token0/1.
    ///      And thus changes the original sequence of fee updates from:
    ///       1) getUnstakedFee() -> feeGrowthGlobal0X128 += x  -> gaugeFees.token0 += y
    ///       2) getUnstakedFee() -> feeGrowthGlobal1X128 += x' -> gaugeFees.token1 += y'
    ///      to:
    ///       1) getUnstakedFee() -> gaugeFees.token0 += y
    ///       2) getUnstakedFee() -> gaugeFees.token1 += y'
    ///       3) feeGrowthGlobal0X128 += x
    ///       4) feeGrowthGlobal1X128 += x'
    (uint256 feeGrowthDelta0, uint256 feeGrowthDelta1) = CL.flash(
      gaugeFees,
      CL.FlashInput({
        token0: token0,
        token1: token1,
        factory: factory,
        tickSpacing: tickSpacing,
        liquidity: liquidity,
        stakedLiquidity: stakedLiquidity,
        recipient: recipient,
        amount0: amount0,
        amount1: amount1
      }),
      data
    );
    if (feeGrowthDelta0 > 0) feeGrowthGlobal0X128 += feeGrowthDelta0;
    if (feeGrowthDelta1 > 0) feeGrowthGlobal1X128 += feeGrowthDelta1;
    _unlock();
  }

  /// @inheritdoc ICLPoolState
  function getRewardGrowthInside(
    int24 tickLower,
    int24 tickUpper,
    uint256 _rewardGrowthGlobalX128
  ) external view override returns (uint256 rewardGrowthInside) {
    return CL.getRewardGrowthInside(
      ticks, tickLower, tickUpper, slot0.tick, _rewardGrowthGlobalX128, rewardGrowthGlobalX128
    );
  }

  /// @dev Seconds elapsed converted into X128 seconds per unit of staked liquidity.
  function _secondsPerStakedLiquidityDelta(uint256 _elapsed, uint128 _stakedLiquidity) internal pure returns (uint160) {
    return uint160((_elapsed << 128) / _stakedLiquidity);
  }

  /// @dev Credits realized emissions to the accumulator when staked liquidity is in range, otherwise banks
  ///      them into rollover, then advances the settlement timestamp. Both settlement paths terminate here.
  function _updateRewardsGrowthGlobal(uint256 _rewardsToDistribute, uint48 _now, uint48 _lastUpdated) internal {
    uint128 _stakedLiquidity = stakedLiquidity;
    if (_stakedLiquidity > 0) {
      rewardGrowthGlobalX128 += FullMath.mulDiv(_rewardsToDistribute, FixedPoint128.Q128, _stakedLiquidity);
      secondsPerStakedLiquidityCumulativeX128 += _secondsPerStakedLiquidityDelta(_now - _lastUpdated, _stakedLiquidity);
    } else {
      rollover += _rewardsToDistribute;
    }
    lastUpdated = _now;
  }

  /// @dev Realizes rewards up to the current block by pulling the emissions accrued since the last
  /// settlement through the gauge. Calls {_updateRewardsGrowthGlobal} to update the rewards to
  /// distribute and lastUpdated. The LeafVoter's settlement is permissionless and returns 0 for
  /// unregistered gauges, so the gauge pull reverts in exactly one case: the gauge's factory relays
  /// the settle to the gauge tape inside a gas-capped call, and the caller funded the settle but
  /// not that capped subcall.
  function _settleToBlock() internal {
    uint48 _timestamp = uint48(block.timestamp);
    uint48 _lastUpdated = lastUpdated;
    if (_timestamp == _lastUpdated) return;

    address _gauge = gauge;
    if (_gauge == address(0)) return;

    uint256 _rewardsToDistribute = ICLGauge(_gauge).settleGauge();
    _updateRewardsGrowthGlobal(_rewardsToDistribute, _timestamp, _lastUpdated);
  }

  /// @inheritdoc ICLPoolActions
  function settleToBlock() external override returns (uint256 _rollover) {
    _lock();
    _onlyGauge();
    _settleToBlock();
    _rollover = rollover;
    delete rollover;
    _unlock();
  }

  /// @notice Calculates the fees owed to staked liquidity, then calculates fee levied on unstaked liquidity
  /// @param feeAmount Total fees
  /// @param _liquidity Current liquidity in active tick
  /// @param _stakedLiquidity Current staked liquidity in active tick
  /// @return unstakedFeeAmount Fee amount for unstaked LPs after accounting for staked liquidity contribution and unstaked fee
  /// @return stakedFeeAmount Fee amount for staked LPs consisting of staked liquidity contribution and unstaked fee
  function splitFees(
    uint256 feeAmount,
    uint128 _liquidity,
    uint128 _stakedLiquidity
  ) internal view returns (uint256 unstakedFeeAmount, uint256 stakedFeeAmount) {
    stakedFeeAmount = FullMath.mulDivRoundingUp(feeAmount, _stakedLiquidity, _liquidity);
    (unstakedFeeAmount, stakedFeeAmount) = applyUnstakedFees(feeAmount - stakedFeeAmount, stakedFeeAmount);
  }

  /// @notice Calculates fee for levied on unstaked liquidity only
  /// @param _unstakedFeeAmount Fee amount for unstaked LPs net of staked liquidity contribution
  /// @param _stakedFeeAmount Fee amount for staked LPs consisting of staked liquidity contribution
  /// @return unstakedFeeAmount Fee amount for unstaked LPs after accounting for staked liquidity contribution and unstaked fee
  /// @return stakedFeeAmount Fee amount for staked LPs consisting of staked liquidity contribution and unstaked fee
  function applyUnstakedFees(
    uint256 _unstakedFeeAmount,
    uint256 _stakedFeeAmount
  ) internal view returns (uint256 unstakedFeeAmount, uint256 stakedFeeAmount) {
    uint256 _stakedFee = FullMath.mulDivRoundingUp(_unstakedFeeAmount, unstakedFee(), 1_000_000);
    unstakedFeeAmount = _unstakedFeeAmount - _stakedFee;
    stakedFeeAmount = _stakedFeeAmount + _stakedFee;
  }

  // calculates the fee growths for unstaked liquidity and returns it with the staked fee amount
  function calculateFees(
    uint256 feeAmount,
    uint128 _liquidity,
    uint128 _stakedLiquidity
  ) internal view returns (uint256 feeGrowthGlobalX128, uint256 stakedFeeAmount) {
    // if there is only staked liquidity
    if (_liquidity == _stakedLiquidity) {
      stakedFeeAmount = feeAmount;
    }
    // if there is only unstaked liquidity
    else if (_stakedLiquidity == 0) {
      (uint256 unstakedFeeAmount, uint256 _stakedFeeAmount) = applyUnstakedFees(feeAmount, 0);
      feeGrowthGlobalX128 = FullMath.mulDiv(unstakedFeeAmount, FixedPoint128.Q128, _liquidity);
      stakedFeeAmount = _stakedFeeAmount;
    }
    // if there are staked and unstaked liquidities
    else {
      (uint256 unstakedFeeAmount, uint256 _stakedFeeAmount) = splitFees(feeAmount, _liquidity, _stakedLiquidity);
      feeGrowthGlobalX128 = FullMath.mulDiv(unstakedFeeAmount, FixedPoint128.Q128, _liquidity - _stakedLiquidity);
      stakedFeeAmount = _stakedFeeAmount;
    }
  }

  /// @inheritdoc ICLPoolOwnerActions
  function collectFees(address recipient) external override returns (uint128 amount0, uint128 amount1) {
    _lock();
    _onlyGauge();
    (amount0, amount1) = CL.collectFees(gaugeFees, recipient, token0, token1);
    _unlock();
  }

  /// @inheritdoc ICLPoolActions
  function setGaugeAndPositionManager(address _gauge, address _nft) external override {
    _lock();
    CL.validateGaugeFactory(factoryRegistry, factory);
    require(gauge == address(0));
    gauge = _gauge;
    nft = _nft;
    // Pull any emissions the voter accrued before the gauge was connected. No liquidity can be
    // staked yet, so the accrual banks into rollover instead of crediting future stakers, and the
    // gauge's settlement cursor is initialized in the same call.
    uint256 _rewardsToDistribute = ICLGauge(_gauge).settleGauge();
    _updateRewardsGrowthGlobal(_rewardsToDistribute, uint48(block.timestamp), lastUpdated);
    _unlock();
  }
}

contracts/core/indexation/CLFactoryIndex.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import {ICLFactoryIndexation} from '../interfaces/indexation/ICLFactoryIndexation.sol';
import {EnumerableSet} from '@openzeppelin/contracts/utils/EnumerableSet.sol';

/**
 * @title CLFactoryIndexation
 * @notice Exposes on-chain indexes for CL pools. The indexes are append-only and
 *         must be updated atomically on each pool creation by the child
 *         CL factory contract through the use of {_createPoolHook}.
 * @dev Exposed indexes are:
 *      1) POOL-BY-TOKEN index: maps a token address to the array of pools in which the token appears.
 *      2) POOLS index: provides a record of all pools created by the child factory, along with their creation timestamps.
 *      3) TOKEN index: contains all unique tokens that have ever appeared in any pool created by the child factory.
 */
abstract contract CLFactoryIndexation is ICLFactoryIndexation {
  using EnumerableSet for EnumerableSet.AddressSet;

  /*////////////////////////////////////////////////////////////
                              STORAGE
  ////////////////////////////////////////////////////////////*/

  /// @inheritdoc ICLFactoryIndexation
  /// @dev {token => pools}
  mapping(address => address[]) public override poolByTokenIndex;

  /// @inheritdoc ICLFactoryIndexation
  PoolData[] public override poolsIndex;

  /// @dev TOKEN index stores tokens used in pools created by the child factory.
  EnumerableSet.AddressSet private tokenIndex;

  /*////////////////////////////////////////////////////////////
                              ERRORS
  ////////////////////////////////////////////////////////////*/

  /// @dev Thrown when end argument to the pagination function
  ///      is less than or equal to the start argument.
  ///      When end < start: we revert instead of substituting
  ///      `end` with the actual length.
  ///      When end == start: we revert instead of returning an empty array.
  string private constant ERR_END_LEQ_START = 'end <= start';

  /*////////////////////////////////////////////////////////////
                              LENGTH FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /// @inheritdoc ICLFactoryIndexation
  function poolByTokenIndexLength(address _token) external view override returns (uint256 _length) {
    _length = poolByTokenIndex[_token].length;
  }

  /// @inheritdoc ICLFactoryIndexation
  function poolsIndexLength() external view override returns (uint256 _length) {
    _length = poolsIndex.length;
  }

  /// @inheritdoc ICLFactoryIndexation
  function tokenIndexLength() external view override returns (uint256 _length) {
    _length = tokenIndex.length();
  }

  /*////////////////////////////////////////////////////////////
                              PAGINATION FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /// @inheritdoc ICLFactoryIndexation
  function poolByTokenIndexPaginated(
    address _token,
    uint256 _start,
    uint256 _end
  ) external view override returns (address[] memory _poolByTokenIndexPaginated) {
    if (_end <= _start) revert(ERR_END_LEQ_START);

    uint256 _len = _end - _start;
    _poolByTokenIndexPaginated = new address[](_len);

    address[] storage pools = poolByTokenIndex[_token];

    for (uint256 _i = 0; _i < _len; ++_i) {
      _poolByTokenIndexPaginated[_i] = pools[_i + _start];
    }
  }

  /// @inheritdoc ICLFactoryIndexation
  function poolsIndexPaginated(
    uint256 _start,
    uint256 _end
  ) external view override returns (PoolData[] memory _poolsIndexPaginated) {
    if (_end <= _start) revert(ERR_END_LEQ_START);

    uint256 _len = _end - _start;
    _poolsIndexPaginated = new PoolData[](_len);

    for (uint256 _i = 0; _i < _len; ++_i) {
      _poolsIndexPaginated[_i] = poolsIndex[_i + _start];
    }
  }

  /// @inheritdoc ICLFactoryIndexation
  function tokenIndexPaginated(
    uint256 _start,
    uint256 _end
  ) external view override returns (address[] memory _tokenIndexPaginated) {
    if (_end <= _start) revert(ERR_END_LEQ_START);

    uint256 _len = _end - _start;
    _tokenIndexPaginated = new address[](_len);

    for (uint256 _i = 0; _i < _len; ++_i) {
      _tokenIndexPaginated[_i] = tokenIndex.at(_start + _i);
    }
  }

  /*////////////////////////////////////////////////////////////
                              INTERNAL FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /**
   * @notice This method populates all indexes with parameters used to create the pool by the child factory.
   * @param _tokenA One of the tokens used to create `_pool`.
   * @param _tokenB One of the tokens used to create `_pool`.
   * @param _pool An address of a newly created pool.
   */
  function _createPoolHook(address _tokenA, address _tokenB, address _pool) internal {
    /// @dev 1) Populates POOL-BY-TOKEN index for both tokens with newly created pool.
    poolByTokenIndex[_tokenA].push(_pool);
    poolByTokenIndex[_tokenB].push(_pool);

    /// @dev 2) Populates POOLS index with newly created pool.
    poolsIndex.push(PoolData({pool: _pool, creationTimestamp: uint48(block.timestamp)}));

    /// @dev 3) Populates TOKEN index with tokens, used to create a new pool.
    ///      {add} is no-op for duplicate elements.
    tokenIndex.add(_tokenA);
    tokenIndex.add(_tokenB);
  }
}

contracts/core/interfaces/ICLFactory.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

import {IFactoryRegistry} from 'contracts/core/interfaces/IFactoryRegistry.sol';
import {ILeafVoter} from 'contracts/gauge/interfaces/ILeafVoter.sol';

/// @title The interface for the CL Factory
/// @notice The CL Factory facilitates creation of CL pools and control over the protocol fees
interface ICLFactory {
  /// @notice An initial tick spacing and its default swap fee, in millionths.
  /// @param tickSpacing Minimum distance between initialized ticks.
  /// @param fee Default swap fee, in millionths.
  struct FeeTier {
    int24 tickSpacing;
    uint24 fee;
  }

  /// @notice Dependencies, initial managers and fee tiers of a newly deployed factory.
  /// @param owner Initial factory owner.
  /// @param swapFeeManager Initial swap fee manager.
  /// @param unstakedFeeManager Initial unstaked fee manager.
  /// @param voter Leaf voter, or zero until configured.
  /// @param poolImplementation Implementation cloned for new pools.
  /// @param positionManager Canonical position manager.
  /// @param factoryRegistry Registry that approves the factory and records its pools.
  /// @param defaultSwapHook Initial swap hook, or zero until configured.
  /// @param discountRegistryManager Initial discount registry manager.
  /// @param clPoolTapeManager Initial pool tape manager.
  /// @param initialFeeTiers Tick spacings and fees enabled during construction.
  struct ConstructorParams {
    address owner;
    address swapFeeManager;
    address unstakedFeeManager;
    address voter;
    address poolImplementation;
    address positionManager;
    address factoryRegistry;
    address defaultSwapHook;
    address discountRegistryManager;
    address clPoolTapeManager;
    FeeTier[] initialFeeTiers;
  }

  /// @notice Emitted when the owner of the factory is changed
  /// @param oldOwner The owner before the owner was changed
  /// @param newOwner The owner after the owner was changed
  event OwnerChanged(address indexed oldOwner, address indexed newOwner);

  /// @notice Emitted when the swapFeeManager of the factory is changed
  /// @param oldFeeManager The swapFeeManager before the swapFeeManager was changed
  /// @param newFeeManager The swapFeeManager after the swapFeeManager was changed
  event SwapFeeManagerChanged(address indexed oldFeeManager, address indexed newFeeManager);

  /// @notice Emitted when the unstakedFeeManager of the factory is changed
  /// @param oldFeeManager The unstakedFeeManager before the unstakedFeeManager was changed
  /// @param newFeeManager The unstakedFeeManager after the unstakedFeeManager was changed
  event UnstakedFeeManagerChanged(address indexed oldFeeManager, address indexed newFeeManager);

  /// @notice Emitted when the default swap hook of the factory is changed
  /// @param swapHook The default swap hook after it was changed
  event DefaultSwapHookChanged(address indexed swapHook);

  /// @notice Emitted when the swap hook of a specific pool is changed
  /// @param pool The pool whose swap hook was changed
  /// @param swapHook The pool swap hook after it was changed
  event PoolSwapHookChanged(address indexed pool, address indexed swapHook);

  /// @notice Emitted when the unstakedFeeModule of the factory is changed
  /// @param oldFeeModule The unstakedFeeModule before the unstakedFeeModule was changed
  /// @param newFeeModule The unstakedFeeModule after the unstakedFeeModule was changed
  event UnstakedFeeModuleChanged(address indexed oldFeeModule, address indexed newFeeModule);

  /// @notice Emitted when the defaultUnstakedFee of the factory is changed
  /// @param oldUnstakedFee The defaultUnstakedFee before the defaultUnstakedFee was changed
  /// @param newUnstakedFee The defaultUnstakedFee after the unstakedFeeModule was changed
  event DefaultUnstakedFeeChanged(uint24 indexed oldUnstakedFee, uint24 indexed newUnstakedFee);

  /// @notice Emitted when the discountRegistryManager of the factory is changed
  /// @param discountRegistryManager The discountRegistryManager after the discountRegistryManager was changed
  event DiscountRegistryManagerChanged(address indexed discountRegistryManager);

  /// @notice Emitted when the discountRegistry of the factory is changed
  /// @param discountRegistry The discountRegistry after the discountRegistry was changed
  event DiscountRegistryChanged(address indexed discountRegistry);

  /// @notice Emitted when the clPoolTape module of the factory is set or cleared
  /// @param clPoolTape The clPoolTape address after the change. The zero address disables tape registration
  event ClPoolTapeChanged(address indexed clPoolTape);

  /// @notice Emitted when the clPoolTapeManager of the factory is changed
  /// @param clPoolTapeManager The clPoolTapeManager after the change
  event ClPoolTapeManagerChanged(address indexed clPoolTapeManager);

  /// @notice Emitted when the voter of the factory is set
  /// @param voter The voter after it was set
  event VoterSet(address indexed voter);

  /// @notice Emitted when a pool is created
  /// @param token0 The first token of the pool by address sort order
  /// @param token1 The second token of the pool by address sort order
  /// @param tickSpacing The minimum number of ticks between initialized ticks
  /// @param pool The address of the created pool
  event PoolCreated(address indexed token0, address indexed token1, int24 indexed tickSpacing, address pool);

  /// @notice Emitted when a new tick spacing is enabled for pool creation via the factory
  /// @param tickSpacing The minimum number of ticks between initialized ticks for pools
  /// @param fee The default fee for a pool created with a given tickSpacing
  event TickSpacingEnabled(int24 indexed tickSpacing, uint24 indexed fee);

  /// @notice The LeafVoter contract, used to check gauge activation for unstaked fees
  /// @dev May be the zero address until set via setVoter, as the voter can be deployed
  ///      after the factory. Unstaked fees are zero until it is set
  /// @return The address of the LeafVoter contract
  function voter() external view returns (ILeafVoter);

  /// @notice The address of the pool implementation contract used to deploy proxies / clones
  /// @return The address of the pool implementation contract
  function poolImplementation() external view returns (address);

  /// @notice The canonical position manager for pools created by this factory
  /// @return The address of the nonfungible position manager
  function positionManager() external view returns (address);

  /// @notice Factory registry that records pools as gauge targets
  /// @dev Set at construction. Every created pool is registered as a target;
  ///      pool creation reverts until this factory is an approved target factory
  ///      in the registry
  /// @return The address of the factory registry
  function factoryRegistry() external view returns (IFactoryRegistry);

  /// @notice Returns the current owner of the factory
  /// @dev Can be changed by the current owner via setOwner
  /// @return The address of the factory owner
  function owner() external view returns (address);

  /// @notice Returns the current swapFeeManager of the factory
  /// @dev Can be changed by the current swap fee manager via setSwapFeeManager
  /// @return The address of the factory swapFeeManager
  function swapFeeManager() external view returns (address);

  /// @notice Returns the current unstakedFeeManager of the factory
  /// @dev Can be changed by the current unstaked fee manager via setUnstakedFeeManager
  /// @return The address of the factory unstakedFeeManager
  function unstakedFeeManager() external view returns (address);

  /// @notice Returns the factory-wide default swap hook used when a pool has no hook set
  /// @dev Can be changed by the current swap fee manager via setDefaultSwapHook
  /// @return The address of the factory defaultSwapHook
  function defaultSwapHook() external view returns (address);

  /// @notice Returns the swap hook override set for a specific pool.
  /// @param pool The pool to query
  /// @return The pool swap hook override, or address(0) if unset
  function poolSwapHook(address pool) external view returns (address);

  /// @notice Resolves the swap hook address for a pool. If the pool doesn't have a swap hook specified,
  ///         then the default hook address is returned.
  /// @param pool The pool to resolve the swap hook for
  /// @return The swap hook address for the pool
  function getPoolSwapHook(address pool) external view returns (address);

  /// @notice Returns the current unstakedFeeModule of the factory
  /// @dev Can be changed by the current unstaked fee manager via setUnstakedFeeModule
  /// @return The address of the factory unstakedFeeModule
  function unstakedFeeModule() external view returns (address);

  /// @notice Returns the current defaultUnstakedFee of the factory
  /// @dev Can be changed by the current unstaked fee manager via setDefaultUnstakedFee
  /// @return The default Unstaked Fee of the factory
  function defaultUnstakedFee() external view returns (uint24);

  /// @notice The current manager of {discountRegistry} of the factory
  /// @return The address of the discount registry manager
  function discountRegistryManager() external view returns (address);

  /// @notice Discount registry for swap fee discounts
  /// @return The address of the discount registry
  function discountRegistry() external view returns (address);

  /// @notice The clPoolTape module new pools are registered with. The zero address means registration is disabled
  /// @return The address of the clPoolTape module
  function clPoolTape() external view returns (address);

  /// @notice The current clPoolTapeManager of the factory
  /// @dev Can be changed by the current clPoolTapeManager via setClPoolTapeManager
  /// @return The address of the clPoolTapeManager
  function clPoolTapeManager() external view returns (address);

  /// @notice Returns a default fee for a tick spacing.
  /// @dev Use getFee for the most up to date fee for a given pool.
  /// A tick spacing can never be removed, so this value should be hard coded or cached in the calling context
  /// @param tickSpacing The enabled tick spacing. Returns 0 if not enabled
  /// @return fee The default fee for the given tick spacing
  function tickSpacingToFee(int24 tickSpacing) external view returns (uint24 fee);

  /// @notice Returns a list of enabled tick spacings. Used to iterate through pools created by the factory
  /// @dev Tick spacings cannot be removed. Tick spacings are not ordered
  /// @return List of enabled tick spacings
  function tickSpacings() external view returns (int24[] memory);

  /// @notice Returns the pool address for a given pair of tokens and a tick spacing, or address 0 if it does not exist
  /// @dev tokenA and tokenB may be passed in either token0/token1 or token1/token0 order
  /// @param tokenA The contract address of either token0 or token1
  /// @param tokenB The contract address of the other token
  /// @param tickSpacing The tick spacing of the pool in uint24
  /// @return pool The pool address
  function getPool(address tokenA, address tokenB, uint24 tickSpacing) external view returns (address pool);

  /// @notice Returns the pool address for a given pair of tokens and a tick spacing, or address 0 if it does not exist
  /// @dev tokenA and tokenB may be passed in either token0/token1 or token1/token0 order
  /// @param tokenA The contract address of either token0 or token1
  /// @param tokenB The contract address of the other token
  /// @param tickSpacing The tick spacing of the pool
  /// @return pool The pool address
  function getPool(address tokenA, address tokenB, int24 tickSpacing) external view returns (address pool);

  /// @notice Return address of pool created by this factory given its `index`
  /// @param index Index of the pool
  /// @return The pool address in the given index
  function allPools(uint256 index) external view returns (address);

  /// @notice Returns the number of pools created from this factory
  /// @return Number of pools created from this factory
  function allPoolsLength() external view returns (uint256);

  /// @notice Used in VotingEscrow to determine if a contract is a valid pool of the factory
  /// @param pool The address of the pool to check
  /// @return Whether the pool is a valid pool of the factory
  function isPool(address pool) external view returns (bool);

  /// @notice Get unstaked fee for a given pool. Accounts for default and dynamic fees
  /// @dev Unstaked fee is denominated in pips. i.e. 1e-6
  /// @param pool The pool to get the unstaked fee for
  /// @return The unstaked fee for the given pool
  function getUnstakedFee(address pool) external view returns (uint24);

  /// @notice Creates a pool for the given two tokens and tick spacing
  /// @param tokenA One of the two tokens in the desired pool
  /// @param tokenB The other of the two tokens in the desired pool
  /// @param tickSpacing The desired tick spacing for the pool
  /// @dev Use encodeSqrtPrice(1,1) as price
  /// @dev Used to programmatically create pools in case one does not exist
  /// @dev Invalid tickSpacing will revert the transaction
  /// @return pool The address of the newly created pool
  function createPool(address tokenA, address tokenB, uint24 tickSpacing) external returns (address pool);

  /// @notice Creates a pool for the given two tokens and tick spacing
  /// @param tokenA One of the two tokens in the desired pool
  /// @param tokenB The other of the two tokens in the desired pool
  /// @param tickSpacing The desired tick spacing for the pool
  /// @param sqrtPriceX96 The initial sqrt price of the pool, as a Q64.96
  /// @dev tokenA and tokenB may be passed in either order: token0/token1 or token1/token0. The call will
  /// revert if the pool already exists, the tick spacing is invalid, or the token arguments are invalid
  /// @return pool The address of the newly created pool
  function createPool(
    address tokenA,
    address tokenB,
    int24 tickSpacing,
    uint160 sqrtPriceX96
  ) external returns (address pool);

  /// @notice Updates the owner of the factory
  /// @dev Must be called by the current owner
  /// @param _owner The new owner of the factory
  function setOwner(address _owner) external;

  /// @notice Sets the voter of the factory
  /// @dev Must be called by the current owner. Callable only while the voter is unset,
  ///      so once set the voter is immutable. Used when the factory is deployed before the voter
  /// @param _voter The voter of the factory
  function setVoter(address _voter) external;

  /// @notice Updates the swapFeeManager of the factory
  /// @dev Must be called by the current swap fee manager
  /// @param _swapFeeManager The new swapFeeManager of the factory
  function setSwapFeeManager(address _swapFeeManager) external;

  /// @notice Updates the unstakedFeeManager of the factory
  /// @dev Must be called by the current unstaked fee manager
  /// @param _unstakedFeeManager The new unstakedFeeManager of the factory
  function setUnstakedFeeManager(address _unstakedFeeManager) external;

  /// @notice Updates the discountRegistryManager of the factory
  /// @dev Must be called by the current discount registry manager
  /// @param _discountRegistryManager The new discountRegistryManager of the factory
  function setDiscountRegistryManager(address _discountRegistryManager) external;

  /// @notice Updates the unstakedFeeModule of the factory
  /// @dev Must be called by the current unstaked fee manager
  /// @param _unstakedFeeModule The new unstakedFeeModule of the factory
  function setUnstakedFeeModule(address _unstakedFeeModule) external;

  /// @notice Updates the defaultUnstakedFee of the factory
  /// @dev Must be called by the current unstaked fee manager
  /// @param _defaultUnstakedFee The new defaultUnstakedFee of the factory
  function setDefaultUnstakedFee(uint24 _defaultUnstakedFee) external;

  /// @notice Updates the factory-wide default swap hook
  /// @dev Must be called by the current swap fee manager
  /// @param _swapHook The new default swap hook of the factory
  function setDefaultSwapHook(address _swapHook) external;

  /// @notice Sets the swap hook override for a batch of pools
  /// @dev Must be called by the current swap fee manager. Reverts with 'LMM' if the array lengths differ.
  ///      For each pool, passing address(0) clears its override back to the default.
  /// @param _pools The pools to set swap hooks for
  /// @param _swapHooks The new swapHook for each corresponding pool
  function setPoolSwapHook(address[] calldata _pools, address[] calldata _swapHooks) external;

  /// @notice Updates the discountRegistry of the factory
  /// @dev Must be called by the current discount registry manager
  /// @param _discountRegistry The new discountRegistry of the factory
  function setDiscountRegistry(address _discountRegistry) external;

  /// @notice Updates the clPoolTapeManager of the factory
  /// @dev Must be called by the current clPoolTapeManager
  /// @param _clPoolTapeManager The new clPoolTapeManager of the factory
  function setClPoolTapeManager(address _clPoolTapeManager) external;

  /// @notice Sets or clears the clPoolTape module new pools are registered with
  /// @dev Must be called by the clPoolTapeManager. The zero address disables tape registration
  /// @param _clPoolTape The new clPoolTape module address
  function setClPoolTape(address _clPoolTape) external;

  /// @notice Enables a certain tickSpacing
  /// @dev Tick spacings may never be removed once enabled
  /// @param tickSpacing The spacing between ticks to be enforced in the pool
  /// @param fee The default fee associated with a given tick spacing
  function enableTickSpacing(int24 tickSpacing, uint24 fee) external;
}

contracts/core/interfaces/IFactoryRegist.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6;

/**
 * @title IFactoryRegistry
 * @notice Surface of the metadex `FactoryRegistry` the CL stack calls.
 * @dev A pool is a "target" and a pool factory a "target factory". The periphery keeps its own read-only mirror in
 *      `contracts/periphery/interfaces/IV3FactoryRegistry.sol` for the quoters.
 */
interface IFactoryRegistry {
  /**
   * @notice Registers a gauge factory and the target factory it serves as a pair, writing their permanent link.
   * @param gaugeFactory The gauge factory to register.
   * @param targetFactory The target (pool) factory the gauge factory serves.
   */
  function registerFactories(address gaugeFactory, address targetFactory) external;

  /**
   * @notice Records a freshly deployed target. Called by the target factory inside its own creation function.
   * @param target The deployed target (pool).
   */
  function registerTarget(address target) external;

  /**
   * @notice True when a target (pool) factory is in the approval set.
   * @param targetFactory The target factory to check.
   * @return Whether the factory is approved.
   */
  function isTargetFactoryApproved(address targetFactory) external view returns (bool);

  /**
   * @notice The gauge factory serving a target factory.
   * @param targetFactory The target factory to resolve.
   * @return The linked gauge factory, zero for an unlinked factory.
   */
  function targetFactoryToGaugeFactory(address targetFactory) external view returns (address);

  /**
   * @notice The gauge over a target (pool).
   * @param target The target to resolve.
   * @return The gauge for `target`, zero when none is recorded.
   */
  function targetToGauge(address target) external view returns (address);

  /**
   * @notice Effective emission cap for a gauge, resolved through the factory that deployed it.
   * @dev Returns zero when the gauge is unknown or the factory call reverts.
   * @param gauge The gauge to resolve.
   * @return The effective cap in tokens per second.
   */
  function emissionCap(address gauge) external view returns (uint128);
}

