// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity =0.7.6;
pragma abicoder v2;

import {FullMath} from '../FullMath.sol';

import {ICLFactory} from 'contracts/core/interfaces/ICLFactory.sol';
import {ISwapHook} from 'contracts/core/interfaces/hook/ISwapHook.sol';

import {CLPool} from 'contracts/core/CLPool.sol';

/// @notice Helper library for invoking swap hook methods and translating pool swap state into hook inputs.
library SwapHookLib {
  using SwapHookLib for CLPool.SwapState;
  using FullMath for uint256;

  /*////////////////////////////////////////////////////////////
                              CONSTANTS
  ////////////////////////////////////////////////////////////*/

  /// @dev A pips denominator.
  uint256 internal constant _DENOMINATOR = 1e6;

  /// @dev A ceil that fees returned from hook methods can not exceed.
  uint24 internal constant _SWAP_FEE_CEIL = 100_000;

  /*////////////////////////////////////////////////////////////
                              VIEW FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /// @notice Calls the hook's `getBeforeSwapFee` entry point. Falls back to the pool's tick-spacing fee
  ///         when: swap hook is zero address; returned fee is zero.
  /// @param _swapHook Address of the hook contract.
  /// @param _pool Address of the pool making the query.
  /// @param _swapParams Swap context and PRE-SWAP pool state.
  /// @param _factory Pool factory used to obtain the default tick-spacing fee.
  /// @param _tickSpacing Pool's tick spacing.
  /// @return The swap fee applied in the swap loop.
  function getBeforeSwapFee(
    address _swapHook,
    address _pool,
    ISwapHook.SwapParams memory _swapParams,
    address _factory,
    int24 _tickSpacing
  ) internal view returns (uint24) {
    if (_swapHook != address(0)) {
      uint24 _fee = ISwapHook(_swapHook).getBeforeSwapFee(_pool, _swapParams);
      if (_fee > 0) return cap(_fee);
    }

    return ICLFactory(_factory).tickSpacingToFee(_tickSpacing);
  }

  /// @notice Calls the hook's `getAfterSwapFee` entry point.
  /// @param _swapHook Address of the hook contract.
  /// @param _pool Address of the pool making the query.
  /// @param _swapParams Swap context and POST-SWAP pool state.
  /// @param _afterSwapParams POST-SWAP execution state and oracle/liquidity context.
  /// @return The swap fee applied after the swap loop.
  function getAfterSwapFee(
    address _swapHook,
    address _pool,
    ISwapHook.SwapParams memory _swapParams,
    ISwapHook.AfterSwapParams memory _afterSwapParams
  ) internal view returns (uint24) {
    if (_swapHook != address(0)) {
      uint24 _fee = ISwapHook(_swapHook).getAfterSwapFee(_pool, _swapParams, _afterSwapParams);
      if (_fee > 0) return cap(_fee);
    }
  }

  /// @notice Calls the hook's `getFlashFee` entry point. Falls back to the pool's tick-spacing fee
  ///         when: swap hook is zero address.
  /// @param _swapHook Address of the hook contract.
  /// @param _pool Address of the pool making the query.
  /// @param _flashParams Arguments passed to the {CLPool.flash} function.
  /// @param _factory Pool factory used to obtain the default tick-spacing fee.
  /// @param _tickSpacing Pool's tick spacing.
  /// @return The flash fee.
  function getFlashFee(
    address _swapHook,
    address _pool,
    ISwapHook.FlashParams memory _flashParams,
    address _factory,
    int24 _tickSpacing
  ) internal view returns (uint24) {
    if (_swapHook != address(0)) {
      uint24 _fee = ISwapHook(_swapHook).getFlashFee(_pool, _flashParams);
      return cap(_fee);
    }

    return ICLFactory(_factory).tickSpacingToFee(_tickSpacing);
  }

  /*////////////////////////////////////////////////////////////
                              WRITE FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /// @notice Calls the hook's `beforeSwap` entry point. Falls back to the pool's tick-spacing fee
  ///         when: swap hook is zero address; returned fee is zero.
  /// @param _swapHook Address of the hook contract.
  /// @param _swapParams Swap context passed to the hook.
  /// @param _factory Pool factory used to obtain the default tick-spacing fee.
  /// @param _tickSpacing Pool's tick spacing.
  /// @return The fee to apply throughout the swap loop.
  function beforeSwap(
    address _swapHook,
    ISwapHook.SwapParams memory _swapParams,
    address _factory,
    int24 _tickSpacing
  ) internal returns (uint24) {
    if (_swapHook != address(0)) {
      uint24 _fee = ISwapHook(_swapHook).beforeSwap(_swapParams);
      if (_fee > 0) return cap(_fee);
    }

    return ICLFactory(_factory).tickSpacingToFee(_tickSpacing);
  }

  /// @notice Calls the hook's `afterSwap` entry point and credits any returned post-swap fee to gauge fees.
  /// @param _swapHook Address of the hook contract.
  /// @param _swapParams Swap context passed to the hook.
  /// @param _state Mutable swap state used to derive the post-swap adjustment.
  /// @param _cache Swap cache used to derive the post-swap hook parameters.
  /// @param gaugeFees Storage gauge fee accumulator updated with any computed post-swap fee.
  function afterSwap(
    address _swapHook,
    ISwapHook.SwapParams memory _swapParams,
    CLPool.SwapState memory _state,
    CLPool.SwapCache memory _cache,
    CLPool.GaugeFees storage gaugeFees
  ) internal {
    if (_swapHook == address(0)) return;

    uint24 _fee = ISwapHook(_swapHook).afterSwap(_swapParams, _state.toAfterSwapParams(_cache));
    if (_fee == 0) return;

    _fee = cap(_fee);

    bool _exactInput = _swapParams.amountSpecified > 0;

    // 1. Get the abs amount of the token that was swapped.
    //    exactInput  (output token)
    //    exactOutput (input token)
    uint256 _swapAmount = _exactInput ? uint256(-_state.amountCalculated) : uint256(_state.amountCalculated);

    // 2. Compute fee in token units.
    uint256 _feeAmount = _swapAmount.mulDivRoundingUp(_fee, _DENOMINATOR);

    // 3. Apply the fee directly to amountCalculated.
    //    exactInput:  amountCalculated is negative => adding a fee to it
    //                 decreases the output the swapper receives.
    //    exactOutput: amountCalculated is positive => adding a fee to it
    //                 increases the input taken from the swapper.
    _state.amountCalculated += int256(_feeAmount);

    // 4. Credit the fee difference to the gauge.
    //    We can't mutate "exact" amount, hence
    //    we're mutating calculated parts of the swap.
    if (_exactInput) {
      // Credit OUTPUT token difference to the gauge.
      if (_swapParams.zeroForOne) gaugeFees.token1 += uint128(_feeAmount);
      else gaugeFees.token0 += uint128(_feeAmount);
    } else {
      // Credit INPUT token difference to the gauge.
      if (_swapParams.zeroForOne) gaugeFees.token0 += uint128(_feeAmount);
      else gaugeFees.token1 += uint128(_feeAmount);
    }
  }

  /// @notice Calls the hook's `beforeFlash` entry point. Falls back to the pool's tick-spacing fee
  ///         when swap hook is zero address.
  /// @param _swapHook Address of the hook contract.
  /// @param _flashParams Arguments passed to the {CLPool.flash} function.
  /// @param _factory Pool factory used to obtain the default tick-spacing fee.
  /// @param _tickSpacing Pool's tick spacing.
  /// @return The fee to apply to flash loaned amounts.
  function beforeFlash(
    address _swapHook,
    ISwapHook.FlashParams memory _flashParams,
    address _factory,
    int24 _tickSpacing
  ) internal returns (uint24) {
    if (_swapHook != address(0)) {
      uint24 _fee = ISwapHook(_swapHook).beforeFlash(_flashParams);
      return cap(_fee);
    }

    return ICLFactory(_factory).tickSpacingToFee(_tickSpacing);
  }

  /*////////////////////////////////////////////////////////////
                              HELPERS
  ////////////////////////////////////////////////////////////*/

  /// @notice Converts pool swap state and cache values into the hook's after-swap parameter struct.
  /// @param _state Current swap state.
  /// @param _cache Current swap cache.
  /// @return _afterSwapParams Converted state and cache of the swap.
  function toAfterSwapParams(
    CLPool.SwapState memory _state,
    CLPool.SwapCache memory _cache
  ) internal pure returns (ISwapHook.AfterSwapParams memory _afterSwapParams) {
    _afterSwapParams = ISwapHook.AfterSwapParams({
      amountSpecifiedRemaining: _state.amountSpecifiedRemaining,
      amountCalculated: _state.amountCalculated,
      fee: _state.fee,
      hasUpdatedFees: _state.hasUpdatedFees,
      feeGrowthGlobalX128: _state.feeGrowthGlobalX128,
      gaugeFee: _state.gaugeFee,
      liquidity: _state.liquidity,
      stakedLiquidity: _state.stakedLiquidity,
      tickCumulative: _cache.tickCumulative,
      secondsPerLiquidityCumulativeX128: _cache.secondsPerLiquidityCumulativeX128,
      computedLatestObservation: _cache.computedLatestObservation
    });
  }

  /// @notice Caps the provided `_fee` with `_SWAP_FEE_CEIL`.
  /// @param _fee The fee returned from the hook method.
  /// @return _cappedFee Capped fee: min(_fee, _SWAP_FEE_CEIL)
  function cap(uint24 _fee) internal pure returns (uint24 _cappedFee) {
    _cappedFee = _fee < _SWAP_FEE_CEIL ? _fee : _SWAP_FEE_CEIL;
  }
}

contracts/core/interfaces/IERC20Minimal..content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Minimal ERC20 interface for CL
/// @notice Contains a subset of the full ERC20 interface that is used in CL
interface IERC20Minimal {
  /// @notice Returns the balance of a token
  /// @param account The account for which to look up the number of tokens it has, i.e. its balance
  /// @return The number of tokens held by the account
  function balanceOf(address account) external view returns (uint256);

  /// @notice Transfers the amount of token from the `msg.sender` to the recipient
  /// @param recipient The account that will receive the amount transferred
  /// @param amount The number of tokens to send from the sender to the recipient
  /// @return Returns true for a successful transfer, false for an unsuccessful transfer
  function transfer(address recipient, uint256 amount) external returns (bool);

  /// @notice Returns the current allowance given to a spender by an owner
  /// @param owner The account of the token owner
  /// @param spender The account of the token spender
  /// @return The current allowance granted by `owner` to `spender`
  function allowance(address owner, address spender) external view returns (uint256);

  /// @notice Sets the allowance of a spender from the `msg.sender` to the value `amount`
  /// @param spender The account which will be allowed to spend a given amount of the owners tokens
  /// @param amount The amount of tokens allowed to be used by `spender`
  /// @return Returns true for a successful approval, false for unsuccessful
  function approve(address spender, uint256 amount) external returns (bool);

  /// @notice Transfers `amount` tokens from `sender` to `recipient` up to the allowance given to the `msg.sender`
  /// @param sender The account from which the transfer will be initiated
  /// @param recipient The recipient of the transfer
  /// @param amount The amount of the transfer
  /// @return Returns true for a successful transfer, false for unsuccessful
  function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);

  /// @notice Event emitted when tokens are transferred from one address to another, either via `#transfer` or `#transferFrom`.
  /// @param from The account from which the tokens were sent, i.e. the balance decreased
  /// @param to The account to which the tokens were sent, i.e. the balance increased
  /// @param value The amount of tokens that were transferred
  event Transfer(address indexed from, address indexed to, uint256 value);

  /// @notice Event emitted when the approval amount for the spender of a given owner's tokens changes.
  /// @param owner The account that approved spending of its tokens
  /// @param spender The account for which the spending allowance was modified
  /// @param value The new allowance from the owner to the spender
  event Approval(address indexed owner, address indexed spender, uint256 value);
}

contracts/core/interfaces/callback/ICLSw.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Callback for ICLPoolActions#swap
/// @notice Any contract that calls ICLPoolActions#swap must implement this interface
interface ICLSwapCallback {
  /// @notice Called to `msg.sender` after executing a swap via ICLPool#swap.
  /// @dev In the implementation you must pay the pool tokens owed for the swap.
  /// The caller of this method must be checked to be a CLPool deployed by the canonical CLFactory.
  /// amount0Delta and amount1Delta can both be 0 if no tokens were swapped.
  /// @param amount0Delta The amount of token0 that was sent (negative) or must be received (positive) by the pool by
  /// the end of the swap. If positive, the callback must send that amount of token0 to the pool.
  /// @param amount1Delta The amount of token1 that was sent (negative) or must be received (positive) by the pool by
  /// the end of the swap. If positive, the callback must send that amount of token1 to the pool.
  /// @param data Any data passed through by the caller via the ICLPoolActions#swap call
  function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external;
}

contracts/core/interfaces/hook/ISwapHook.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.7.6;
pragma abicoder v2;

/// @notice Interface for CLPool swap hooks that can override pre-swap fees and/or apply post-swap fees.
interface ISwapHook {
  /*////////////////////////////////////////////////////////////
                              STRUCTS
  ////////////////////////////////////////////////////////////*/

  /// @notice Swap context passed to hook entry points.
  /// @param caller `msg.sender` address that initiated the swap.
  /// @param recipient Recipient of the swap output.
  /// @param zeroForOne True for token0 -> token1 swaps, false otherwise.
  /// @param amountSpecified The exact amount specified by the swapper (either input or output).
  /// @param sqrtPriceLimitX96 Swap price limit.
  /// @param data Optional calldata supplied to the swap call.
  /// @param sqrtPriceX96 Square root price of the pool:
  ///        In {beforeSwap} represents a PRE-SWAP sqrt price.
  ///        In {afterSwap} represents a POST-SWAP sqrt price.
  /// @param tick Tick of the pool:
  ///        In {beforeSwap} represents a PRE-SWAP tick.
  ///        In {afterSwap} represents a POST-SWAP tick.
  struct SwapParams {
    address caller;
    address recipient;
    bool zeroForOne;
    int256 amountSpecified;
    uint160 sqrtPriceLimitX96;
    bytes data;
    uint160 sqrtPriceX96;
    int24 tick;
  }

  /// @notice Post-swap state passed to the {afterSwap} entry-point.
  /// @param amountSpecifiedRemaining Remaining specified amount after the swap loop conclusion.
  /// @param amountCalculated Amount computed by the swap loop before any post-swap fee adjustment.
  /// @param fee The fee applied during the swap loop.
  /// @param hasUpdatedFees Whether swap fees were updated during execution.
  /// @param feeGrowthGlobalX128 The global fee growth of the input token after the swap loop.
  /// @param gaugeFee Fee amount paid to staked liquidity.
  /// @param liquidity In-range liquidity at the end of the swap loop.
  /// @param stakedLiquidity In-range staked liquidity at the end of the swap loop.
  /// @param tickCumulative The post-swap value of the tick accumulator, computed only if an initialized tick is crossed.
  /// @param secondsPerLiquidityCumulativeX128 The post-swap value of the seconds per liquidity
  ///        accumulator, computed only if an initialized tick is crossed.
  /// @param computedLatestObservation Whether the latest observation was computed during the swap.
  struct AfterSwapParams {
    int256 amountSpecifiedRemaining;
    int256 amountCalculated;
    uint24 fee;
    bool hasUpdatedFees;
    uint256 feeGrowthGlobalX128;
    uint128 gaugeFee;
    uint128 liquidity;
    uint128 stakedLiquidity;
    int56 tickCumulative;
    uint160 secondsPerLiquidityCumulativeX128;
    bool computedLatestObservation;
  }

  /// @notice Call context of `flash` function.
  /// @param caller `msg.sender` address that initiated flash execution.
  /// @param recipient Recipient of the flash loaned tokens.
  /// @param amount0 Amount of token0 to flash loan.
  /// @param amount1 Amount of token1 to flash loan.
  /// @param data Optional calldata supplied to the flash call.
  struct FlashParams {
    address caller;
    address recipient;
    uint256 amount0;
    uint256 amount1;
    bytes data;
  }

  /*////////////////////////////////////////////////////////////
                              VIEW FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /// @notice Queries the swap fee that the hook would charge in the swap loop.
  /// @param _pool Address of the pool making the query.
  /// @param _swapParams Swap context and pre-swap pool state.
  /// @return _fee The fee that would be applied in the swap loop, in pips.
  function getBeforeSwapFee(address _pool, SwapParams memory _swapParams) external view returns (uint24 _fee);

  /// @notice Queries the swap fee that the hook would charge after the swap loop.
  /// @param _pool Address of the pool making the query.
  /// @param _swapParams Swap context and post-swap pool state.
  /// @param _afterSwapParams Post-swap execution state and oracle/liquidity context.
  /// @return _fee The fee that would be applied after the swap loop, in pips.
  function getAfterSwapFee(
    address _pool,
    SwapParams memory _swapParams,
    AfterSwapParams memory _afterSwapParams
  ) external view returns (uint24 _fee);

  /// @notice Queries the flash loan fee that the hook would charge for a given flash context.
  /// @param _pool Address of the pool making the query.
  /// @param _flashParams Arguments passed to the flash function.
  /// @return _fee The fee that would be applied to flash loaned amounts, in pips.
  function getFlashFee(address _pool, FlashParams memory _flashParams) external view returns (uint24 _fee);

  /*////////////////////////////////////////////////////////////
                              WRITE FUNCTIONS
  ////////////////////////////////////////////////////////////*/

  /// @notice Returns the fee to apply inside the swap loop.
  /// @param _swapParams Swap context and PRE-SWAP pool state.
  /// @return _fee The fee to apply throughout the swap loop.
  function beforeSwap(SwapParams memory _swapParams) external returns (uint24 _fee);

  /// @notice Returns the pips fee to apply after the swap loop conclusion.
  /// @dev The fee is redirected exclusively to the Gauge.
  /// @param _swapParams Swap context and POST-SWAP pool state.
  /// @param _afterSwapParams POST-SWAP execution state and oracle/liquidity context.
  /// @return _fee A post-swap fee to apply to the non-exact input/output part
  ///         of the swap that's credited to the gauge.
  function afterSwap(
    SwapParams memory _swapParams,
    AfterSwapParams memory _afterSwapParams
  ) external returns (uint24 _fee);

  /// @notice Returns the fee to apply to `amount0/1` in `flash` function.
  /// @param _flashParams Arguments passed to the `flash` function.
  /// @return _fee Fee to apply to flash loaned amounts.
  function beforeFlash(FlashParams memory _flashParams) external returns (uint24 _fee);
}

contracts/gauge/interfaces/ICLGauge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

import {ICLPool} from 'contracts/gauge/interfaces/ICLPool.sol';
import {IGauge} from 'contracts/gauge/interfaces/IGauge.sol';
import {INonfungiblePositionManager} from 'contracts/gauge/interfaces/INonfungiblePositionManager.sol';

interface ICLGauge is IGauge {
  /**
   * @notice Emitted when a position is deposited into the gauge.
   * @param _caller The address that deposited the position.
   * @param _user The address credited as the staked owner.
   * @param _tokenId The tokenId of the deposited position.
   * @param _liquidityToStake The amount of liquidity staked in the pool.
   */
  event Deposit(address indexed _caller, address indexed _user, uint256 indexed _tokenId, uint128 _liquidityToStake);

  /**
   * @notice Emitted when a position is withdrawn from the gauge.
   * @param _caller The address that withdrew the position.
   * @param _user The address whose stake was withdrawn.
   * @param _tokenId The tokenId of the withdrawn position.
   * @param _liquidityToStake The amount of liquidity unstaked from the pool.
   */
  event Withdraw(address indexed _caller, address indexed _user, uint256 indexed _tokenId, uint128 _liquidityToStake);

  /**
   * @notice Emitted when accrued emissions are claimed for a staked position.
   * @param _account The address of the LP staker whose emissions were claimed.
   * @param _tokenId The tokenId of the staked position.
   * @param _recipient The recipient of the claimed emissions.
   * @param _rewardAmount The amount of emissions paid to the recipient.
   */
  event EmissionsClaimed(
    address indexed _account, uint256 indexed _tokenId, address indexed _recipient, uint256 _rewardAmount
  );

  /**
   * @notice Emitted when accrued emissions are stored instead of claimed during withdrawal.
   * @param _account The address of the LP staker credited with the deferred emissions.
   * @param _tokenId The tokenId whose emissions were stored.
   * @param _rewardAmount The post-penalty, post-referral emissions added to the account's deferred balance.
   */
  event EmissionsDeferred(address indexed _account, uint256 indexed _tokenId, uint256 _rewardAmount);

  /**
   * @notice Emitted when a position's referral emissions are stored for a later claim.
   * @param _account The address of the LP staker whose emissions paid the referral.
   * @param _tokenId The tokenId of the staked position.
   * @param _referral The referral address credited with the emissions.
   * @param _amount The referral emissions added to the referral's deferred balance.
   */
  event ReferralEmissionsDeferred(
    address indexed _account, uint256 indexed _tokenId, address indexed _referral, uint256 _amount
  );

  /**
   * @notice Emitted when an account's deferred emissions are claimed.
   * @param _account The account whose deferred emissions were claimed.
   * @param _recipient The recipient of the claimed emissions.
   * @param _amount The deferred emissions paid to the recipient after referral.
   */
  event DeferredEmissionsClaimed(address indexed _account, address indexed _recipient, uint256 _amount);

  /**
   * @notice Emitted when an early withdrawal penalty is applied to a position's accrued emissions.
   * @param _from The address of the LP staker whose emissions were penalized.
   * @param _tokenId The tokenId of the staked position.
   * @param _penalty The amount of emissions forfeited as the penalty.
   */
  event EarlyWithdrawPenalty(address indexed _from, uint256 indexed _tokenId, uint256 _penalty);

  /**
   * @notice Emitted when a per-tokenId withdrawal approval is set or cleared
   * @param _owner The position owner
   * @param _operator The approved operator (address(0) if cleared)
   * @param _tokenId The approved token ID
   */
  event Approval(address indexed _owner, address indexed _operator, uint256 indexed _tokenId);

  /**
   * @notice Emitted when the gauge settles emissions accrued in the LeafVoter
   * @dev Not emitted when a settlement accrues no new emissions
   * @param _cumulativeRewardShare The LeafVoter's cumulative reward share at this settlement
   * @param _delta The emissions accrued since the previous settlement
   */
  event GaugeSettled(uint256 _cumulativeRewardShare, uint256 _delta);

  /**
   * @notice Called on gauge creation by CLGaugeFactory
   * @dev Only callable by the gauge factory
   * @param _pool The address of the pool
   * @param _votingRewardsManager The address of the voting rewards manager contract
   * @param _token0 The address of token0 of the pool
   * @param _token1 The address of token1 of the pool
   * @param _tickSpacing The tick spacing of the pool
   * @param _isPool Whether the attached pool is a real pool or not
   */
  function initialize(
    address _pool,
    address _votingRewardsManager,
    address _token0,
    address _token1,
    int24 _tickSpacing,
    bool _isPool
  ) external;

  /**
   * @notice Settle the gauge in the LeafVoter and return the emissions accrued since the last settlement
   * @dev Only callable by the corresponding pool
   * @dev Pulls the gauge's cumulative reward share from the LeafVoter and advances the gauge's cursor
   * @dev Reports the settle to the gauge tape through the factory: a full report when the cursor
   *      advances, a refresh when it holds at a nonzero level, nothing on a regression
   * @return _delta The emissions accrued since the gauge's last settlement
   */
  function settleGauge() external returns (uint256 _delta);

  /**
   * @notice Settle the pool and forfeit any accumulated rollover back to the LeafVoter
   * @dev Permissionless. Emissions accrued while no staked liquidity is in range are banked in the
   *      pool as rollover and normally forfeited during claims; an idle gauge with no staked
   *      positions has no claims, so this entrypoint returns them to the voter directly.
   */
  function forfeitRollover() external;

  /**
   * @notice Claim the LP's accrued emissions across the given positions
   * @dev Also claims all account-level deferred LP emissions regardless of the requested positions
   * @param _account The address of the LP staker whose emissions are being claimed
   * @param _recipient The recipient of the claimed emissions
   * @param _tokenIds The staked positions to claim
   */
  function claimEmissions(address _account, address _recipient, uint256[] calldata _tokenIds) external;

  /**
   * @notice NonfungiblePositionManager used to create nfts accepted by this gauge.
   * @return The address of the NonfungiblePositionManager.
   */
  function nft() external view returns (INonfungiblePositionManager);

  /**
   * @notice Address of the CL pool linked to the gauge.
   * @return The address of the CL pool.
   */
  function pool() external view returns (ICLPool);

  /**
   * @notice Cached address of token0, corresponding to token0 of the pool.
   * @return The address of token0.
   */
  function token0() external view returns (address);

  /**
   * @notice Cached address of token1, corresponding to token1 of the pool.
   * @return The address of token1.
   */
  function token1() external view returns (address);

  /**
   * @notice Cached tick spacing of the pool.
   * @return The tick spacing of the pool.
   */
  function tickSpacing() external view returns (int24);

  /**
   * @notice Returns the rewardGrowthInside of the position at the last user action (deposit, withdraw, claimEmissions)
   * @param _tokenId The tokenId of the position
   * @return The rewardGrowthInside for the position
   */
  function rewardGrowthInside(uint256 _tokenId) external view returns (uint256);

  /**
   * @notice Returns the block number at which a position was deposited
   * @param _tokenId The tokenId of the position
   * @return The deposit block for the position
   */
  function depositBlock(uint256 _tokenId) external view returns (uint256);

  /**
   * @notice Returns net LP emissions stored for an account when emission minting fails during withdrawal
   * @param _account The account credited with the deferred emissions
   * @return The post-penalty, post-referral deferred LP emissions
   */
  function deferredEmissions(address _account) external view returns (uint256);

  /**
   * @notice Estimates the claimable emissions for a given account across the requested positions
   * @dev Assumes _tokenIds contains no duplicates
   * @dev Rewards accrued since the last settlement are an estimate
   * @dev Includes the account-level deferred LP emissions
   * @param _account The address of the LP staker
   * @param _tokenIds The staked positions
   * @return The estimated claimable amount
   */
  function earned(address _account, uint256[] memory _tokenIds) external view returns (uint256);

  /**
   * @notice Returns the operator approved to withdraw a specific staked position
   * @param _tokenId The staked NFT token ID
   * @return The approved operator, or address(0) if none
   */
  function getApproved(uint256 _tokenId) external view returns (address);

  /**
   * @notice Fetch all tokenIds staked by a given account
   * @param _depositor The address of the user
   * @return The tokenIds of the staked positions
   */
  function stakedValues(address _depositor) external view returns (uint256[] memory);

  /**
   * @notice Fetch a staked tokenId by index
   * @param _depositor The address of the user
   * @param _index The index of the staked tokenId
   * @return The tokenId of the staked position
   */
  function stakedByIndex(address _depositor, uint256 _index) external view returns (uint256);

  /**
   * @notice Check whether a position is staked in the gauge by a certain user
   * @param _depositor The address of the user
   * @param _tokenId The tokenId of the position
   * @return Whether the position is staked in the gauge
   */
  function stakedContains(address _depositor, uint256 _tokenId) external view returns (bool);

  /**
   * @notice The amount of positions staked in the gauge by a certain user
   * @param _depositor The address of the user
   * @return The amount of positions staked in the gauge
   */
  function stakedLength(address _depositor) external view returns (uint256);
}

