// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;
pragma abicoder v2;

import {ISwapHook} from '../hook/ISwapHook.sol';

/// @title Pool state that can change
/// @notice These methods compose the pool's state, and can change with any frequency including multiple times
/// per transaction
interface ICLPoolState {
  /// @notice The 0th storage slot in the pool stores many values, and is exposed as a single method to save gas
  /// when accessed externally.
  /// @return sqrtPriceX96 The current price of the pool as a sqrt(token1/token0) Q64.96 value
  /// tick The current tick of the pool, i.e. according to the last tick transition that was run.
  /// This value may not always be equal to SqrtTickMath.getTickAtSqrtRatio(sqrtPriceX96) if the price is on a tick
  /// boundary.
  /// observationIndex The index of the last oracle observation that was written,
  /// observationCardinality The current maximum number of observations stored in the pool,
  /// observationCardinalityNext The next maximum number of observations, to be updated when the observation.
  /// unlocked Whether the pool is currently locked to reentrancy
  function slot0()
    external
    view
    returns (
      uint160 sqrtPriceX96,
      int24 tick,
      uint16 observationIndex,
      uint16 observationCardinality,
      uint16 observationCardinalityNext,
      bool unlocked
    );

  /// @notice The pool's pre-swap swap fee in pips, i.e. 1e-6
  /// @param _swapParams Swap context and pre-swap pool state.
  /// @return The pre-swap fee.
  function beforeSwapFee(ISwapHook.SwapParams memory _swapParams) external view returns (uint24);

  /// @notice The pool's post-swap swap fee in pips, i.e. 1e-6
  /// @param _swapParams Swap context and post-swap pool state.
  /// @param _afterSwapParams Post-swap execution state and oracle/liquidity context.
  /// @return The post-swap fee.
  function afterSwapFee(
    ISwapHook.SwapParams memory _swapParams,
    ISwapHook.AfterSwapParams memory _afterSwapParams
  ) external view returns (uint24);

  /// @notice The pool's flash fee in pips, i.e. 1e-6
  /// @param _flashParams Arguments passed to the flash function.
  /// @return The flash fee.
  function flashFee(ISwapHook.FlashParams memory _flashParams) external view returns (uint24);

  /// @notice The pool's swap fee in pips, i.e. 1e-6
  /// @return The swap fee.
  function fee() external view returns (uint24);

  /// @notice The pool's unstaked fee in pips, i.e. 1e-6
  /// @dev Can be modified in PoolFactory on a pool basis or upgraded to be dynamic.
  /// @return The unstaked fee
  function unstakedFee() external view returns (uint24);

  /// @notice The fee growth as a Q128.128 fees of token0 collected per unit of liquidity for the entire life of the pool
  /// @dev This value can overflow the uint256
  function feeGrowthGlobal0X128() external view returns (uint256);

  /// @notice The fee growth as a Q128.128 fees of token1 collected per unit of liquidity for the entire life of the pool
  /// @dev This value can overflow the uint256
  function feeGrowthGlobal1X128() external view returns (uint256);

  /// @notice The reward growth as a Q128.128 rewards of emission collected per unit of liquidity for the entire life of the pool
  /// @dev This value can overflow the uint256
  function rewardGrowthGlobalX128() external view returns (uint256);

  /// @notice The cumulative seconds per unit of in-range staked liquidity as of lastUpdated
  /// @return The Q128.128 stored seconds per staked liquidity cumulative
  function secondsPerStakedLiquidityCumulativeX128() external view returns (uint160);

  /// @notice The amounts of token0 and token1 that are owed to the gauge
  /// @dev Gauge fees will never exceed uint128 max in either token
  function gaugeFees() external view returns (uint128 token0, uint128 token1);

  /// @notice Last time the pool reward growth was advanced
  function lastUpdated() external view returns (uint48);

  /// @notice Emissions accrued while no staked liquidity was in range
  function rollover() external view returns (uint256);

  /// @notice The currently in range liquidity available to the pool
  /// @dev This value has no relationship to the total liquidity across all ticks
  /// @dev This value includes staked liquidity
  function liquidity() external view returns (uint128);

  /// @notice The currently in range staked liquidity available to the pool
  /// @dev This value has no relationship to the total staked liquidity across all ticks
  function stakedLiquidity() external view returns (uint128);

  /// @notice Look up information about a specific tick in the pool
  /// @param tick The tick to look up
  /// @return liquidityGross the total amount of position liquidity that uses the pool either as tick lower or
  /// tick upper,
  /// liquidityNet how much liquidity changes when the pool price crosses the tick,
  /// stakedLiquidityNet how much staked liquidity changes when the pool price crosses the tick,
  /// feeGrowthOutside0X128 the fee growth on the other side of the tick from the current tick in token0,
  /// feeGrowthOutside1X128 the fee growth on the other side of the tick from the current tick in token1,
  /// rewardGrowthOutsideX128 the reward growth on the other side of the tick from the current tick in emission token
  /// tickCumulativeOutside the cumulative tick value on the other side of the tick from the current tick
  /// secondsPerLiquidityOutsideX128 the seconds spent per liquidity on the other side of the tick from the current tick,
  /// secondsOutside the seconds spent on the other side of the tick from the current tick,
  /// initialized Set to true if the tick is initialized, i.e. liquidityGross is greater than 0, otherwise equal to false.
  /// Outside values can only be used if the tick is initialized, i.e. if liquidityGross is greater than 0.
  /// In addition, these values are only relative and must be used only in comparison to previous snapshots for
  /// a specific position.
  function ticks(int24 tick)
    external
    view
    returns (
      uint128 liquidityGross,
      int128 liquidityNet,
      int128 stakedLiquidityNet,
      uint256 feeGrowthOutside0X128,
      uint256 feeGrowthOutside1X128,
      uint256 rewardGrowthOutsideX128,
      int56 tickCumulativeOutside,
      uint160 secondsPerLiquidityOutsideX128,
      uint32 secondsOutside,
      bool initialized
    );

  /// @notice Returns 256 packed tick initialized boolean values. See TickBitmap for more information
  function tickBitmap(int16 wordPosition) external view returns (uint256);

  /// @notice Returns the information about a position by the position's key
  /// @param key The position's key is a hash of a preimage composed by the owner, tickLower and tickUpper
  /// @return _liquidity The amount of liquidity in the position,
  /// Returns feeGrowthInside0LastX128 fee growth of token0 inside the tick range as of the last mint/burn/poke,
  /// Returns feeGrowthInside1LastX128 fee growth of token1 inside the tick range as of the last mint/burn/poke,
  /// Returns tokensOwed0 the computed amount of token0 owed to the position as of the last mint/burn/poke,
  /// Returns tokensOwed1 the computed amount of token1 owed to the position as of the last mint/burn/poke
  function positions(bytes32 key)
    external
    view
    returns (
      uint128 _liquidity,
      uint256 feeGrowthInside0LastX128,
      uint256 feeGrowthInside1LastX128,
      uint128 tokensOwed0,
      uint128 tokensOwed1
    );

  /// @notice Returns data about a specific observation index
  /// @param index The element of the observations array to fetch
  /// @dev You most likely want to use #observe() instead of this method to get an observation as of some amount of time
  /// ago, rather than at a specific index in the array.
  /// @return blockTimestamp The timestamp of the observation,
  /// Returns tickCumulative the tick multiplied by seconds elapsed for the life of the pool as of the observation timestamp,
  /// Returns secondsPerLiquidityCumulativeX128 the seconds per in range liquidity for the life of the pool as of the observation timestamp,
  /// Returns initialized whether the observation has been initialized and the values are safe to use
  function observations(uint256 index)
    external
    view
    returns (uint32 blockTimestamp, int56 tickCumulative, uint160 secondsPerLiquidityCumulativeX128, bool initialized);

  /// @notice Returns data about reward growth within a tick range.
  /// RewardGrowthGlobalX128 can be supplied as a parameter for claimable reward calculations.
  /// @dev Used in gauge reward/earned calculations
  /// @param tickLower The lower tick of the range
  /// @param tickUpper The upper tick of the range
  /// @param _rewardGrowthGlobalX128 a calculated rewardGrowthGlobalX128 or 0 (in case of 0 it means we use the rewardGrowthGlobalX128 from state)
  /// @return rewardGrowthInsideX128 The reward growth in the range
  function getRewardGrowthInside(
    int24 tickLower,
    int24 tickUpper,
    uint256 _rewardGrowthGlobalX128
  ) external view returns (uint256 rewardGrowthInsideX128);

  /// @notice Returns data about fee growth within a tick range.
  /// @param tickLower The lower tick of the range
  /// @param tickUpper The upper tick of the range
  /// @return feeGrowthInside0X128 The token0 fee growth in range.
  /// @return feeGrowthInside1X128 The token1 fee growth in range.
  function getFeeGrowthInside(
    int24 tickLower,
    int24 tickUpper
  ) external view returns (uint256 feeGrowthInside0X128, uint256 feeGrowthInside1X128);
}

contracts/core/libraries/BitMath.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title BitMath
/// @dev This library provides functionality for computing bit properties of an unsigned integer
library BitMath {
  /// @notice Returns the index of the most significant bit of the number,
  ///     where the least significant bit is at index 0 and the most significant bit is at index 255
  /// @dev The function satisfies the property:
  ///     x >= 2**mostSignificantBit(x) and x < 2**(mostSignificantBit(x)+1)
  /// @param x the value for which to compute the most significant bit, must be greater than 0
  /// @return r the index of the most significant bit
  function mostSignificantBit(uint256 x) internal pure returns (uint8 r) {
    require(x > 0);

    if (x >= 0x100000000000000000000000000000000) {
      x >>= 128;
      r += 128;
    }
    if (x >= 0x10000000000000000) {
      x >>= 64;
      r += 64;
    }
    if (x >= 0x100000000) {
      x >>= 32;
      r += 32;
    }
    if (x >= 0x10000) {
      x >>= 16;
      r += 16;
    }
    if (x >= 0x100) {
      x >>= 8;
      r += 8;
    }
    if (x >= 0x10) {
      x >>= 4;
      r += 4;
    }
    if (x >= 0x4) {
      x >>= 2;
      r += 2;
    }
    if (x >= 0x2) r += 1;
  }

  /// @notice Returns the index of the least significant bit of the number,
  ///     where the least significant bit is at index 0 and the most significant bit is at index 255
  /// @dev The function satisfies the property:
  ///     (x & 2**leastSignificantBit(x)) != 0 and (x & (2**(leastSignificantBit(x)) - 1)) == 0)
  /// @param x the value for which to compute the least significant bit, must be greater than 0
  /// @return r the index of the least significant bit
  function leastSignificantBit(uint256 x) internal pure returns (uint8 r) {
    require(x > 0);

    r = 255;
    if (x & type(uint128).max > 0) {
      r -= 128;
    } else {
      x >>= 128;
    }
    if (x & type(uint64).max > 0) {
      r -= 64;
    } else {
      x >>= 64;
    }
    if (x & type(uint32).max > 0) {
      r -= 32;
    } else {
      x >>= 32;
    }
    if (x & type(uint16).max > 0) {
      r -= 16;
    } else {
      x >>= 16;
    }
    if (x & type(uint8).max > 0) {
      r -= 8;
    } else {
      x >>= 8;
    }
    if (x & 0xf > 0) {
      r -= 4;
    } else {
      x >>= 4;
    }
    if (x & 0x3 > 0) {
      r -= 2;
    } else {
      x >>= 2;
    }
    if (x & 0x1 > 0) r -= 1;
  }
}

contracts/core/libraries/SqrtPriceMath.s.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

import './LowGasSafeMath.sol';
import './SafeCast.sol';

import './FixedPoint96.sol';
import './FullMath.sol';
import './UnsafeMath.sol';

/// @title Functions based on Q64.96 sqrt price and liquidity
/// @notice Contains the math that uses square root of price as a Q64.96 and liquidity to compute deltas
library SqrtPriceMath {
  using LowGasSafeMath for uint256;
  using SafeCast for uint256;

  /// @notice Gets the next sqrt price given a delta of token0
  /// @dev Always rounds up, because in the exact output case (increasing price) we need to move the price at least
  /// far enough to get the desired output amount, and in the exact input case (decreasing price) we need to move the
  /// price less in order to not send too much output.
  /// The most precise formula for this is liquidity * sqrtPX96 / (liquidity +- amount * sqrtPX96),
  /// if this is impossible because of overflow, we calculate liquidity / (liquidity / sqrtPX96 +- amount).
  /// @param sqrtPX96 The starting price, i.e. before accounting for the token0 delta
  /// @param liquidity The amount of usable liquidity
  /// @param amount How much of token0 to add or remove from virtual reserves
  /// @param add Whether to add or remove the amount of token0
  /// @return The price after adding or removing amount, depending on add
  function getNextSqrtPriceFromAmount0RoundingUp(
    uint160 sqrtPX96,
    uint128 liquidity,
    uint256 amount,
    bool add
  ) internal pure returns (uint160) {
    // we short circuit amount == 0 because the result is otherwise not guaranteed to equal the input price
    if (amount == 0) return sqrtPX96;
    uint256 numerator1 = uint256(liquidity) << FixedPoint96.RESOLUTION;

    if (add) {
      uint256 product;
      if ((product = amount * sqrtPX96) / amount == sqrtPX96) {
        uint256 denominator = numerator1 + product;
        if (denominator >= numerator1) {
          // always fits in 160 bits
          return uint160(FullMath.mulDivRoundingUp(numerator1, sqrtPX96, denominator));
        }
      }

      return uint160(UnsafeMath.divRoundingUp(numerator1, (numerator1 / sqrtPX96).add(amount)));
    } else {
      uint256 product;
      // if the product overflows, we know the denominator underflows
      // in addition, we must check that the denominator does not underflow
      require((product = amount * sqrtPX96) / amount == sqrtPX96 && numerator1 > product);
      uint256 denominator = numerator1 - product;
      return FullMath.mulDivRoundingUp(numerator1, sqrtPX96, denominator).toUint160();
    }
  }

  /// @notice Gets the next sqrt price given a delta of token1
  /// @dev Always rounds down, because in the exact output case (decreasing price) we need to move the price at least
  /// far enough to get the desired output amount, and in the exact input case (increasing price) we need to move the
  /// price less in order to not send too much output.
  /// The formula we compute is within <1 wei of the lossless version: sqrtPX96 +- amount / liquidity
  /// @param sqrtPX96 The starting price, i.e., before accounting for the token1 delta
  /// @param liquidity The amount of usable liquidity
  /// @param amount How much of token1 to add, or remove, from virtual reserves
  /// @param add Whether to add, or remove, the amount of token1
  /// @return The price after adding or removing `amount`
  function getNextSqrtPriceFromAmount1RoundingDown(
    uint160 sqrtPX96,
    uint128 liquidity,
    uint256 amount,
    bool add
  ) internal pure returns (uint160) {
    // if we're adding (subtracting), rounding down requires rounding the quotient down (up)
    // in both cases, avoid a mulDiv for most inputs
    if (add) {
      uint256 quotient =
        (amount <= type(uint160).max
          ? (amount << FixedPoint96.RESOLUTION) / liquidity
          : FullMath.mulDiv(amount, FixedPoint96.Q96, liquidity));

      return uint256(sqrtPX96).add(quotient).toUint160();
    } else {
      uint256 quotient =
        (amount <= type(uint160).max
          ? UnsafeMath.divRoundingUp(amount << FixedPoint96.RESOLUTION, liquidity)
          : FullMath.mulDivRoundingUp(amount, FixedPoint96.Q96, liquidity));

      require(sqrtPX96 > quotient);
      // always fits 160 bits
      return uint160(sqrtPX96 - quotient);
    }
  }

  /// @notice Gets the next sqrt price given an input amount of token0 or token1
  /// @dev Throws if price or liquidity are 0, or if the next price is out of bounds
  /// @param sqrtPX96 The starting price, i.e., before accounting for the input amount
  /// @param liquidity The amount of usable liquidity
  /// @param amountIn How much of token0, or token1, is being swapped in
  /// @param zeroForOne Whether the amount in is token0 or token1
  /// @return sqrtQX96 The price after adding the input amount to token0 or token1
  function getNextSqrtPriceFromInput(
    uint160 sqrtPX96,
    uint128 liquidity,
    uint256 amountIn,
    bool zeroForOne
  ) internal pure returns (uint160 sqrtQX96) {
    require(sqrtPX96 > 0);
    require(liquidity > 0);

    // round to make sure that we don't pass the target price
    return zeroForOne
      ? getNextSqrtPriceFromAmount0RoundingUp(sqrtPX96, liquidity, amountIn, true)
      : getNextSqrtPriceFromAmount1RoundingDown(sqrtPX96, liquidity, amountIn, true);
  }

  /// @notice Gets the next sqrt price given an output amount of token0 or token1
  /// @dev Throws if price or liquidity are 0 or the next price is out of bounds
  /// @param sqrtPX96 The starting price before accounting for the output amount
  /// @param liquidity The amount of usable liquidity
  /// @param amountOut How much of token0, or token1, is being swapped out
  /// @param zeroForOne Whether the amount out is token0 or token1
  /// @return sqrtQX96 The price after removing the output amount of token0 or token1
  function getNextSqrtPriceFromOutput(
    uint160 sqrtPX96,
    uint128 liquidity,
    uint256 amountOut,
    bool zeroForOne
  ) internal pure returns (uint160 sqrtQX96) {
    require(sqrtPX96 > 0);
    require(liquidity > 0);

    // round to make sure that we pass the target price
    return zeroForOne
      ? getNextSqrtPriceFromAmount1RoundingDown(sqrtPX96, liquidity, amountOut, false)
      : getNextSqrtPriceFromAmount0RoundingUp(sqrtPX96, liquidity, amountOut, false);
  }

  /// @notice Gets the amount0 delta between two prices
  /// @dev Calculates liquidity / sqrt(lower) - liquidity / sqrt(upper),
  /// i.e. liquidity * (sqrt(upper) - sqrt(lower)) / (sqrt(upper) * sqrt(lower))
  /// @param sqrtRatioAX96 A sqrt price
  /// @param sqrtRatioBX96 Another sqrt price
  /// @param liquidity The amount of usable liquidity
  /// @param roundUp Whether to round the amount up or down
  /// @return amount0 Amount of token0 required to cover a position of size liquidity between the two passed prices
  function getAmount0Delta(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint128 liquidity,
    bool roundUp
  ) internal pure returns (uint256 amount0) {
    if (sqrtRatioAX96 > sqrtRatioBX96) (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);

    uint256 numerator1 = uint256(liquidity) << FixedPoint96.RESOLUTION;
    uint256 numerator2 = sqrtRatioBX96 - sqrtRatioAX96;

    require(sqrtRatioAX96 > 0);

    return roundUp
      ? UnsafeMath.divRoundingUp(FullMath.mulDivRoundingUp(numerator1, numerator2, sqrtRatioBX96), sqrtRatioAX96)
      : FullMath.mulDiv(numerator1, numerator2, sqrtRatioBX96) / sqrtRatioAX96;
  }

  /// @notice Gets the amount1 delta between two prices
  /// @dev Calculates liquidity * (sqrt(upper) - sqrt(lower))
  /// @param sqrtRatioAX96 A sqrt price
  /// @param sqrtRatioBX96 Another sqrt price
  /// @param liquidity The amount of usable liquidity
  /// @param roundUp Whether to round the amount up, or down
  /// @return amount1 Amount of token1 required to cover a position of size liquidity between the two passed prices
  function getAmount1Delta(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    uint128 liquidity,
    bool roundUp
  ) internal pure returns (uint256 amount1) {
    if (sqrtRatioAX96 > sqrtRatioBX96) (sqrtRatioAX96, sqrtRatioBX96) = (sqrtRatioBX96, sqrtRatioAX96);

    return roundUp
      ? FullMath.mulDivRoundingUp(liquidity, sqrtRatioBX96 - sqrtRatioAX96, FixedPoint96.Q96)
      : FullMath.mulDiv(liquidity, sqrtRatioBX96 - sqrtRatioAX96, FixedPoint96.Q96);
  }

  /// @notice Helper that gets signed token0 delta
  /// @param sqrtRatioAX96 A sqrt price
  /// @param sqrtRatioBX96 Another sqrt price
  /// @param liquidity The change in liquidity for which to compute the amount0 delta
  /// @return amount0 Amount of token0 corresponding to the passed liquidityDelta between the two prices
  function getAmount0Delta(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    int128 liquidity
  ) internal pure returns (int256 amount0) {
    return liquidity < 0
      ? -getAmount0Delta(sqrtRatioAX96, sqrtRatioBX96, uint128(-liquidity), false).toInt256()
      : getAmount0Delta(sqrtRatioAX96, sqrtRatioBX96, uint128(liquidity), true).toInt256();
  }

  /// @notice Helper that gets signed token1 delta
  /// @param sqrtRatioAX96 A sqrt price
  /// @param sqrtRatioBX96 Another sqrt price
  /// @param liquidity The change in liquidity for which to compute the amount1 delta
  /// @return amount1 Amount of token1 corresponding to the passed liquidityDelta between the two prices
  function getAmount1Delta(
    uint160 sqrtRatioAX96,
    uint160 sqrtRatioBX96,
    int128 liquidity
  ) internal pure returns (int256 amount1) {
    return liquidity < 0
      ? -getAmount1Delta(sqrtRatioAX96, sqrtRatioBX96, uint128(-liquidity), false).toInt256()
      : getAmount1Delta(sqrtRatioAX96, sqrtRatioBX96, uint128(liquidity), true).toInt256();
  }
}

